function getRequestStatusTone(status) {
  if (status === "Cancelada" || status === "Datos incompletos") return "red";
  if (status === "Entregada") return "green";
  if (status === "Lista para entrega") return "teal";
  if (status === "En producción" || status === "En revisión de calidad") return "orange";
  if (status === "Aprobada" || status === "En revisión") return "blue";
  return "purple";
}

function getPriorityTone(priority) {
  if (priority === "Urgente") return "red";
  if (priority === "Alta") return "orange";
  if (priority === "Baja") return "teal";
  return "blue";
}

function getPriorityClassName(priority = "Normal") {
  return `priority-${String(priority || "Normal")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")}`;
}

function parseRequestDate(value) {
  if (!value) return null;

  const date = typeof value?.toDate === "function"
    ? value.toDate()
    : new Date(String(value).includes("T") ? value : `${value}T00:00:00`);

  return Number.isNaN(date.getTime()) ? null : date;
}

function calculateRequestPriority({ requestDate, dueDate, createdAt } = {}) {
  const due = parseRequestDate(dueDate);

  if (!due) return "Normal";

  const start = parseRequestDate(requestDate) || parseRequestDate(createdAt) || new Date();
  const dayMs = 24 * 60 * 60 * 1000;
  const daysToDeliver = Math.ceil((due.getTime() - start.getTime()) / dayMs);

  if (daysToDeliver <= 3) return "Urgente";
  if (daysToDeliver <= 7) return "Alta";
  return "Normal";
}

