function normalizeCredentialTemplatePositions(positions) {
  const defaults = getDefaultCredentialTemplatePositions();
  const source = positions && typeof positions === "object" ? positions : {};

  return ["front", "back"].reduce((nextPositions, side) => {
    const sideSource = source[side] && typeof source[side] === "object" ? source[side] : {};

    nextPositions[side] = Object.keys(defaults[side]).reduce((sidePositions, key) => {
      sidePositions[key] = normalizeTemplatePosition(sideSource[key], defaults[side][key]);
      return sidePositions;
    }, {});

    return nextPositions;
  }, {});
}

function getTemplateElementStyle(position, extra = {}) {
  const { includeHeight, ...restExtra } = extra;
  const normalized = normalizeTemplatePosition(position, {});
  const width = extra.size ? normalized.size : normalized.width;

  return {
    position: "absolute",
    left: `${normalized.x}%`,
    top: `${normalized.y}%`,
    width: `${width}%`,
    ...(includeHeight && normalized.height > 0 ? { height: `${normalized.height}px` } : {}),
    transform: "translate(-50%, -50%)",
    textAlign: "center",
    ...restExtra,
  };
}

function getTemplateSignatureBoxStyle(position) {
  const normalized = normalizeCertificateSignaturePosition(position, {});

  return {
    ...getTemplateElementStyle(normalized),
    width: `${normalized.width}%`,
    height: "auto",
    aspectRatio: `${CERTIFICATE_SIGNATURE_ASPECT_RATIO} / 1`,
    overflow: "visible",
  };
}

function isCertificateSignatureElement(elementKey) {
  return certificateSignatureElementKeys.includes(elementKey);
}

function getProportionalSignaturePosition(elementKey, field, value) {
  const nextValue = field === "active" ? Boolean(value) : Number(value);

  if (!isCertificateSignatureElement(elementKey) || !["width", "height"].includes(field)) {
    return { [field]: nextValue };
  }

  if (field === "width") {
    const width = Math.max(0, Number(value || 0));
    return {
      width,
      height: getCertificateSignatureHeightFromWidth(width),
      aspectRatio: CERTIFICATE_SIGNATURE_ASPECT_RATIO,
    };
  }

  const height = Math.max(0, Number(value || 0));
  return {
    width: getCertificateSignatureWidthFromHeight(height),
    height,
    aspectRatio: CERTIFICATE_SIGNATURE_ASPECT_RATIO,
  };
}

function getTemplateTextStyle(position, extra = {}) {
  const normalized = normalizeTemplatePosition(position, {});
  return getTemplateElementStyle(normalized, {
    fontSize: `${normalized.fontSize}px`,
    ...extra,
  });
}

function getDefaultCertificateBodySegments() {
  return DEFAULT_CERTIFICATE_BODY_SEGMENTS.map((segment) => ({ ...segment }));
}

function createTemplateBodySegmentId() {
  return `seg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeCertificateBodySegment(segment, index = 0) {
  const source = segment && typeof segment === "object" ? segment : {};

  return {
    id: String(source.id || `seg-${index + 1}`),
    text: String(source.text ?? ""),
    bold: source.bold === true,
    italic: source.italic === true,
    underline: source.underline === true,
  };
}

function normalizeCertificateBodySegments(segments, fallbackText = DEFAULT_CERTIFICATE_BODY_TEXT) {
  if (Array.isArray(segments) && segments.length > 0) {
    const normalizedSegments = segments
      .map((segment, index) => normalizeCertificateBodySegment(segment, index))
      .filter((segment) => segment.text.length > 0);

    if (normalizedSegments.length > 0) {
      return normalizedSegments;
    }
  }

  const fallback = String(fallbackText || DEFAULT_CERTIFICATE_BODY_TEXT);

  if (fallback === DEFAULT_CERTIFICATE_BODY_TEXT || fallback.includes("{program}")) {
    return getDefaultCertificateBodySegments();
  }

  return [
    {
      id: "seg-1",
      text: fallback,
      bold: false,
      italic: false,
      underline: false,
    },
  ];
}

function getCertificateBodyTextFromSegments(segments, fallbackText = DEFAULT_CERTIFICATE_BODY_TEXT) {
  return normalizeCertificateBodySegments(segments, fallbackText)
    .map((segment) => segment.text)
    .join("");
}

function getResolvedCertificateBodySegments(segments, fallbackText, programLabel) {
  const program = programLabel || "English course";

  return normalizeCertificateBodySegments(segments, fallbackText).map((segment) => ({
    ...segment,
    text: String(segment.text || "").replaceAll("{program}", program),
  }));
}

