function getStudentDeliveryCounts(students) {
  const normalizedStudents = normalizeRequestStudents(students);

  return normalizedStudents.reduce(
    (totals, student) => {
      const deliveryType = student.deliveryType || "Impreso";

      totals.total += 1;

      if (deliveryType === "Impreso" || deliveryType === "Ambos") {
        totals.printed += 1;
      }

      if (deliveryType === "Digital" || deliveryType === "Ambos") {
        totals.digital += 1;
      }

      return totals;
    },
    { total: 0, printed: 0, digital: 0 }
  );
}

function getStudentValidationSummary(request) {
  const counts = getStudentDeliveryCounts(request?.students);
  const rawRequestedQuantity = Number(request?.requestedQuantity || 0);
  const rawPrintedQuantity = Number(request?.printedQuantity || 0);
  const rawDigitalQuantity = Number(request?.digitalQuantity || 0);
  const shouldUseStudentCounts =
    counts.total > 0 &&
    (
      rawRequestedQuantity === 0 ||
      rawRequestedQuantity !== counts.total ||
      rawPrintedQuantity + rawDigitalQuantity === 0
    );
  const requestedQuantity = shouldUseStudentCounts ? counts.total : rawRequestedQuantity;
  const printedQuantity = shouldUseStudentCounts ? counts.printed : rawPrintedQuantity;
  const digitalQuantity = shouldUseStudentCounts ? counts.digital : rawDigitalQuantity;

  return {
    ...counts,
    requestedQuantity,
    printedQuantity,
    digitalQuantity,
    totalMatches: counts.total === requestedQuantity,
    printedMatches: counts.printed === printedQuantity,
    digitalMatches: counts.digital === digitalQuantity,
  };
}


function formatCertificatePreviewDate(value) {
  if (!value) return "Date pending";

  let date;

  if (typeof value?.toDate === "function") {
    date = value.toDate();
  } else if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const [year, month, day] = value.split("-").map(Number);
    date = new Date(year, month - 1, day);
  } else {
    date = new Date(value);
  }

  if (Number.isNaN(date.getTime())) return "Date pending";

  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

function getCertificateIssueDate(request) {
  return request?.certificateIssueDate || request?.requestDate || request?.dueDate || request?.updatedAt || request?.createdAt || "";
}

function getCertificateTrackLabel(request) {
  if (request?.level && request.level !== "No aplica") {
    const levelMap = {
      A1: "Journey",
      A2: "Explore",
      B1: "Discover",
      B2: "B2",
      C1: "New Horizons",
    };
    return levelMap[request.level] || request.level;
  }

  const productName = String(request?.productName || "").trim();
  return productName || "Active English";
}

function getCertificateProgramLabel(request) {
  const level = request?.level && request.level !== "No aplica" ? request.level : "";
  return level ? `basic English ${level}` : "English course";
}

function getCertificateLevelColor(level) {
  return CERTIFICATE_LEVEL_COLORS[level] || "#0e7a37";
}

function sanitizeFolioSegment(value, fallback = "GEN") {
  const cleaned = String(value || fallback)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .toUpperCase();

  return cleaned || fallback;
}

function getCertificatePrefix(requestType) {
  return requestType === "Diploma" ? "DIPL" : "CERT";
}

function buildCertificateStudentFolio(request, studentIndex) {
  const year = new Date().getFullYear();
  const prefix = getCertificatePrefix(request?.requestType);
  const levelCode = sanitizeFolioSegment(request?.level || "NA", "NA").slice(0, 8);
  const requestCode = sanitizeFolioSegment(request?.folio || request?.id || Date.now(), "REQ")
    .replace(/^IMP-?/, "")
    .slice(-10);
  const consecutive = String(studentIndex).padStart(3, "0");

  return `${prefix}-${year}-${levelCode}-${requestCode}-${consecutive}`;
}

function buildValidationCode(folio) {
  const randomPart = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `${folio}-${randomPart}`;
}

function buildValidationUrl(validationCode) {
  const origin = typeof window !== "undefined" && window.location?.origin
    ? window.location.origin
    : "https://active-english-school.web.app";

  return `${origin}/validar-certificado/${encodeURIComponent(validationCode)}`;
}

function buildCredentialValidationUrl(validationCode) {
  const origin = typeof window !== "undefined" && window.location?.origin
    ? window.location.origin
    : "https://active-english-school.web.app";

  return `${origin}/validar-credencial/${encodeURIComponent(validationCode)}`;
}

function buildCredentialFolio({ department, employeeId } = {}) {
  const year = new Date().getFullYear();
  const departmentCode = sanitizeFolioSegment(department || "CRED", "CRED").slice(0, 8);
  const personCode = sanitizeFolioSegment(employeeId || Date.now(), "ID").slice(-8);
  const suffix = String(Date.now()).slice(-5);

  return `CRED-${year}-${departmentCode}-${personCode}-${suffix}`;
}

function buildCredentialValidationCode(folio) {
  return buildValidationCode(folio);
}

function getRequestProductLabel(request) {
  if (!request) return "Solicitud";

  const baseName = request.productName || request.requestType || "Solicitud";

  if (isRequestCertificateLike(request.requestType) && request.level && request.level !== "No aplica") {
    return `${baseName} ${request.level}`;
  }

  return baseName;
}

function isRequestPending(status) {
  return [
    "Solicitud recibida",
    "Datos incompletos",
    "En revisión",
    "Aprobada",
    "En producción",
    "En revisión de calidad",
  ].includes(status);
}

function getRequestProgress(status) {
  const statusProgress = {
    "Solicitud recibida": 10,
    "Datos incompletos": 8,
    "En revisión": 25,
    Aprobada: 40,
    "En producción": 62,
    "En revisión de calidad": 78,
    "Lista para entrega": 90,
    Entregada: 100,
    Cancelada: 0,
  };

  return statusProgress[status] ?? 0;
}

function getDateValueMs(value) {
  if (!value) return 0;
  if (value?.toDate) return value.toDate().getTime();
  if (value instanceof Date) return value.getTime();

  const parsed = new Date(value).getTime();
  return Number.isNaN(parsed) ? 0 : parsed;
}

function getEffectiveRequestStatus(request) {
  if (!request) return "Solicitud recibida";

  const status = request.status || "Solicitud recibida";
  const readyAtMs = getDateValueMs(request.readyForDeliveryAt);

  if (status === "En producción" && readyAtMs > 0 && readyAtMs <= Date.now()) {
    return "Lista para entrega";
  }

  return status;
}

function getEffectiveRequestStatusTone(request) {
  return getRequestStatusTone(getEffectiveRequestStatus(request));
}

function getEffectiveRequestProgress(request) {
  return getRequestProgress(getEffectiveRequestStatus(request));
}

function getRequestDueLabel(request) {
  if (!request?.dueDate) return "Sin compromiso";

  const date = new Date(`${request.dueDate}T00:00:00`);
  if (Number.isNaN(date.getTime())) return request.dueDate;

  return new Intl.DateTimeFormat("es-MX", {
    dateStyle: "medium",
  }).format(date);
}

function getInventoryStatus(item) {
  const currentStock = Number(item?.currentStock || 0);
  const minStock = Number(item?.minStock || 0);
  const idealStock = Number(item?.idealStock || 0);

  if (currentStock <= 0) {
    return { label: "Crítico", tone: "red" };
  }

  if (minStock > 0 && currentStock < minStock) {
    return { label: "Bajo", tone: "orange" };
  }

  if (idealStock > 0 && currentStock >= idealStock) {
    return { label: "Óptimo", tone: "green" };
  }

  return { label: "Normal", tone: "blue" };
}

