  async function generateCredentialRecord(form) {
    setCredentialMessage("");

    const template = credentialTemplates.find((item) => item.id === form.templateId) || null;

    if (!template) {
      setCredentialMessage("Selecciona una plantilla activa.");
      return null;
    }

    const fullName = String(form.fullName || "").trim();
    const department = String(form.department || "").trim();

    if (!fullName || !department) {
      setCredentialMessage("Indica nombre y departamento.");
      return null;
    }

    const auditUser = getAuditUser();
    const folio = buildCredentialFolio({
      department,
      employeeId: form.employeeId,
    });
    const validationCode = buildCredentialValidationCode(folio);
    const validationUrl = buildCredentialValidationUrl(validationCode);
    const qrDataUrl = await QRCode.toDataURL(validationUrl, {
      margin: 2,
      width: 220,
      errorCorrectionLevel: "M",
    });

    const payload = {
      folio,
      validationCode,
      validationUrl,
      qrDataUrl,
      fullName,
      department,
      position: String(form.position || ""),
      employeeId: String(form.employeeId || ""),
      templateId: template.id,
      templateName: template.name,
      issueDate: String(form.issueDate || ""),
      expiryDate: String(form.expiryDate || ""),
      status: "Generado",
      notes: String(form.notes || ""),
      generatedAt: serverTimestamp(),
      generatedByUid: auditUser.uid,
      generatedByName: auditUser.name,
      generatedByEmail: auditUser.email,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };
    const credentialId = sanitizeGeneratedCertificateId(validationCode || folio);

    try {
      setSavingCredential(true);

      const batch = writeBatch(db);
      batch.set(doc(db, "generatedCredentials", credentialId), payload, { merge: true });
      batch.set(
        doc(db, "publicCredentialValidations", credentialId),
        buildPublicCredentialValidationPayload(payload, {
          publishedAt: serverTimestamp(),
        }),
        { merge: true }
      );

      await batch.commit();
      await createPrintshopLog({
        type: "CREDENTIAL_GENERATED",
        module: "credentials",
        title: "Credencial generada",
        description: `Se genero la credencial de ${fullName}.`,
        referenceType: "credential",
        referenceId: credentialId,
        validationCode,
        studentName: fullName,
        productName: "Credencial",
        level: department,
      });

      const generatedCredential = {
        id: credentialId,
        ...payload,
        generatedAt: new Date().toISOString(),
      };
      setCredentialMessage(`Credencial ${folio} generada correctamente.`);
      return generatedCredential;
    } catch (error) {
      console.error("No se pudo generar la credencial:", error);
      setCredentialMessage("No se pudo generar la credencial. Revisa las reglas de Firestore.");
      return null;
    } finally {
      setSavingCredential(false);
    }
  }

  function handleSignerInputChange(event) {
    const { name, value, type, checked } = event.target;

    setSignerMessage("");
    setSignerForm((current) => {
      if (name === "type") {
        return {
          ...current,
          type: value,
          role: value === "Principal" ? "Principal" : "Teacher",
        };
      }

      return {
        ...current,
        [name]: type === "checkbox" ? checked : value,
      };
    });
  }

  function resetSignerForm({ keepMessage = false } = {}) {
    setSelectedSignerId(null);
    setSignerForm(signerFormInitialState);
    setSignatureFile(null);
    if (!keepMessage) {
      setSignerMessage("");
    }
  }

  function selectSigner(signer) {
    const campusFormState = getCertificateSignerCampusFormState(signer.campus);
    setSelectedSignerId(signer.id);
    setSignerMessage("");
    setSignatureFile(null);
    setSignerForm({
      name: signer.name || "",
      role: signer.role || (signer.type === "Principal" ? "Principal" : "Teacher"),
      type: signer.type || "Teacher",
      ...campusFormState,
      active: signer.active !== false,
      notes: signer.notes || "",
      signatureUrl: signer.signatureUrl || "",
      signatureDataUrl: signer.signatureDataUrl || "",
      storagePath: signer.storagePath || "",
      naturalWidth: Number(signer.naturalWidth || 0),
      naturalHeight: Number(signer.naturalHeight || 0),
      aspectRatio: Number(signer.aspectRatio || 0),
      normalizedAspectRatio: Number(signer.normalizedAspectRatio || CERTIFICATE_SIGNATURE_ASPECT_RATIO),
    });
  }

  async function saveCertificateSigner(event) {
    event.preventDefault();
    setSignerMessage("");

    if (!isAdmin) {
      setSignerMessage("Solo los administradores pueden administrar firmas.");
      return { success: false };
    }

    const auditUser = getAuditUser();
    const name = signerForm.name.trim();
    const role = signerForm.role.trim() || (signerForm.type === "Principal" ? "Principal" : "Teacher");
    const campus = resolveCertificateSignerCampus(signerForm.campus, signerForm.customCampus);

    if (!name) {
      setSignerMessage("Indica el nombre del firmante.");
      return { success: false };
    }

    if (!role) {
      setSignerMessage("Indica el cargo que aparecerá debajo del nombre.");
      return { success: false };
    }

    if (!campus) {
      setSignerMessage("Indica el nombre del plantel.");
      return { success: false };
    }

    if (!selectedSignerId && !signatureFile) {
      setSignerMessage("Sube una imagen de firma para crear el firmante.");
      return { success: false };
    }

    if (signatureFile && !isValidSignatureFile(signatureFile)) {
      setSignerMessage("La firma debe ser PNG, JPG o WEBP y pesar menos de 5 MB.");
      return { success: false };
    }

    try {
      setSavingSigner(true);

      let signatureUrl = signerForm.signatureUrl || "";
      let signatureDataUrl = signerForm.signatureDataUrl || "";
      let storagePath = signerForm.storagePath || "";
      let naturalWidth = Number(signerForm.naturalWidth || 0);
      let naturalHeight = Number(signerForm.naturalHeight || 0);
      let aspectRatio = Number(signerForm.aspectRatio || getImageAspectRatio(naturalWidth, naturalHeight) || 0);
      let normalizedAspectRatio = Number(signerForm.normalizedAspectRatio || CERTIFICATE_SIGNATURE_ASPECT_RATIO);

      if (signatureFile) {
        const signatureFileData = await readSignatureFileData(signatureFile);
        signatureDataUrl = signatureFileData.dataUrl;
        naturalWidth = signatureFileData.naturalWidth;
        naturalHeight = signatureFileData.naturalHeight;
        aspectRatio = signatureFileData.aspectRatio;
        normalizedAspectRatio = signatureFileData.normalizedAspectRatio;
        const safeName = sanitizeStorageFileName(signatureFile.name);
        const folder = getSignerTypeFolder(signerForm.type);
        storagePath = `printshop/signatures/${folder}/${auditUser.uid}/${Date.now()}-${safeName}`;
        const fileRef = storageRef(storage, storagePath);

        await uploadBytes(fileRef, signatureFile, {
          contentType: signatureFile.type,
        });
        signatureUrl = await getDownloadURL(fileRef);
      } else if (!aspectRatio && (signatureDataUrl || signatureUrl)) {
        const signatureMetadata = await loadImageMetadataFromSource(signatureDataUrl || signatureUrl);
        naturalWidth = signatureMetadata.naturalWidth;
        naturalHeight = signatureMetadata.naturalHeight;
        aspectRatio = signatureMetadata.aspectRatio;
        normalizedAspectRatio = CERTIFICATE_SIGNATURE_ASPECT_RATIO;
      }

      const payload = {
        name,
        role,
        type: signerForm.type,
        campus,
        active: signerForm.active !== false,
        notes: signerForm.notes || "",
        signatureUrl,
        signatureDataUrl,
        storagePath,
        naturalWidth,
        naturalHeight,
        aspectRatio,
        normalizedAspectRatio,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      };

      let savedSignerId = selectedSignerId;

      if (selectedSignerId) {
        await updateDoc(doc(db, "certificateSigners", selectedSignerId), payload);
        await createPrintshopLog({
          type: "SIGNER_UPDATED",
          module: "signers",
          title: "Firma actualizada",
          description: `Se actualizó la firma de ${name}.`,
          referenceType: "signer",
          referenceId: selectedSignerId,
          campus: payload.campus || "",
        });
        setSignerMessage("Firmante actualizado correctamente.");
      } else {
        const newSignerRef = await addDoc(collection(db, "certificateSigners"), {
          ...payload,
          createdAt: serverTimestamp(),
          createdByUid: auditUser.uid,
          createdByName: auditUser.name,
          createdByEmail: auditUser.email,
        });
        await createPrintshopLog({
          type: "SIGNER_CREATED",
          module: "signers",
          title: "Firma creada",
          description: `Se creó la firma de ${name}.`,
          referenceType: "signer",
          referenceId: newSignerRef.id,
          campus: payload.campus || "",
        });
        setSignerMessage("Firmante creado correctamente.");
        savedSignerId = newSignerRef.id;
      }

      resetSignerForm({ keepMessage: true });
      return { success: true, signerId: savedSignerId };
    } catch (error) {
      console.error("No se pudo guardar la firma:", error);
      setSignerMessage("No se pudo guardar la firma. Revisa reglas de Firestore y Storage.");
      return { success: false };
    } finally {
      setSavingSigner(false);
    }
  }

  async function toggleSignerStatus(signer) {
    if (!isAdmin || !signer?.id) return;

    const auditUser = getAuditUser();

    try {
      await updateDoc(doc(db, "certificateSigners", signer.id), {
        active: signer.active === false,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });
    } catch (error) {
      console.error("No se pudo cambiar el estado del firmante:", error);
      setSignerMessage("No se pudo cambiar el estado del firmante.");
    }
  }

  async function deleteSignerPermanently(signer) {
    if (!isAdmin || !signer?.id) return;

    const confirmed = window.confirm(
      `¿Eliminar definitivamente la firma de ${signer.name || "este firmante"}?\n\nEsta accion borra el registro de Firestore y no se puede deshacer.`
    );

    if (!confirmed) return;

    try {
      if (signer.storagePath) {
        try {
          await deleteObject(storageRef(storage, signer.storagePath));
        } catch (storageError) {
          console.warn("No se pudo eliminar el archivo de firma en Storage:", storageError);
        }
      }

      await deleteDoc(doc(db, "certificateSigners", signer.id));

      setCertificateSigners((current) => current.filter((item) => item.id !== signer.id));
      if (selectedSignerId === signer.id) resetSignerForm();

      try {
        await createPrintshopLog({
          type: "DELETE",
          module: "signers",
          title: `Firma eliminada: ${signer.name || "firmante"}`,
          description: "El firmante se elimino definitivamente de Firestore.",
          referenceType: "certificateSigners",
          referenceId: signer.id,
        });
      } catch (logError) {
        console.warn("La firma se elimino, pero no se pudo guardar la bitacora:", logError);
      }

      setSignerMessage("Firma eliminada definitivamente.");
    } catch (error) {
      console.error("No se pudo eliminar la firma:", error);
      setSignerMessage("No se pudo eliminar la firma. Revisa las reglas de Firestore.");
    }
  }

  function resetRequestForm() {
    setSelectedRequestId(null);
    setRequestForm(requestFormInitialState);
    setRequestMessage("");
    setReprintCertificateStudentId("");
    setStudentName("");
    setStudentDeliveryType("Impreso");
    setBulkStudentsText("");
    setBulkStudentsDeliveryType("Impreso");
  }

  function selectRequest(request) {
    const normalizedAssignments = normalizePrintRequestAssignments(request);
    const assignedUser = activeUsers.find((person) => getUserUid(person) === normalizedAssignments.assignedUserId);
    const supportUser = activeUsers.find((person) => getUserUid(person) === normalizedAssignments.supportUserId);
    const requestLevel = request.level || request.certificateTemplateLevel || "No aplica";
    const requestGroup = request.group || request.courseLevel || request.certificateTemplateProgramName || "";
    const requestStudentCounts = getStudentDeliveryCounts(request.students || []);
    const resolvedRequestedQuantity = Number(request.requestedQuantity || requestStudentCounts.total || 0);
    const resolvedPrintedQuantity = Number(request.printedQuantity || (requestStudentCounts.total ? requestStudentCounts.printed : 0));
    const resolvedDigitalQuantity = Number(request.digitalQuantity || (requestStudentCounts.total ? requestStudentCounts.digital : 0));
    const matchingTemplate =
      request.certificateTemplateId
        ? findCertificateTemplate(request.certificateTemplateId)
        : findMatchingCertificateTemplate(
            {
              ...requestFormInitialState,
              requestType: request.requestType || "Certificado",
              certificateTemplateId: request.certificateTemplateId || "",
              certificateTemplateLevel: request.certificateTemplateLevel || requestLevel,
              certificateTemplateProgramName: request.certificateTemplateProgramName || request.courseProgramName || request.courseLevel || requestGroup,
              certificateTemplateAudience: request.certificateTemplateAudience || request.courseAudience || "",
              courseProgramName: request.courseProgramName || "",
              courseLevel: request.courseLevel || "",
              courseAudience: request.courseAudience || "",
              productName: request.productName || "",
              level: requestLevel,
              group: requestGroup,
            },
            {
              id: request.productId || "",
              name: request.productName || "",
              category: request.requestType || "Certificado",
              level: requestLevel,
            }
          );
    const automaticPriority = calculateRequestPriority({
      requestDate: request.requestDate,
      dueDate: request.dueDate || request.requestedDeliveryDate,
      createdAt: request.createdAt,
    });
    const matchingPrincipalSigner = findMatchingCertificateSigner(
      request.principalSignerId,
      request.principalSignerName || request.certificateDirectorName || request.academicDirector,
      "Principal"
    );
    const matchingTeacherSigner = findMatchingCertificateSigner(
      request.teacherSignerId,
      request.teacherSignerName || request.teacherName,
      "Teacher"
    );

    setSelectedRequestId(request.id);
    setReprintCertificateStudentId("");
    setRequestMessage("");
    setRequestForm({
      productId: request.productId || "",
      requestType: request.requestType || "Volante",
      requesterName: request.requesterName || "",
      requesterArea: request.requesterArea || "",
      campus: request.campus || "Plaza Estrella",
      responsibleUid: normalizedAssignments.assignedUserId,
      responsibleName: request.responsibleName || getUserDisplayName(assignedUser),
      responsibleEmail: request.responsibleEmail || getUserEmail(assignedUser),
      collaboratorUid: normalizedAssignments.supportUserId,
      collaboratorName: request.collaboratorName || getUserDisplayName(supportUser),
      collaboratorEmail: request.collaboratorEmail || getUserEmail(supportUser),
      priority: automaticPriority || request.priority || "Normal",
      requestedQuantity: resolvedRequestedQuantity,
      deliveredQuantity: Number(request.deliveredQuantity || 0),
      deliveryType: request.deliveryType || "Impresa",
      status: normalizePrintRequestStatus(request.status),
      requestDate: request.requestDate || "",
      dueDate: request.dueDate || request.requestedDeliveryDate || "",
      certificateIssueDate: request.certificateIssueDate || request.dueDate || request.requestedDeliveryDate || "",
      certificateTemplateId: request.certificateTemplateId || matchingTemplate?.id || "",
      certificateTemplateName: request.certificateTemplateName || matchingTemplate?.name || "",
      certificateTemplateLevel: request.certificateTemplateLevel || matchingTemplate?.level || "",
      certificateTemplateProgramName: request.certificateTemplateProgramName || matchingTemplate?.programName || "",
      certificateTemplateAudience: request.certificateTemplateAudience || matchingTemplate?.audience || "",
      certificateTemplateBodyText: request.certificateTemplateBodyText || matchingTemplate?.bodyText || "",
      certificateTemplateBodySegments: normalizeCertificateBodySegments(
        request.certificateTemplateBodySegments || matchingTemplate?.bodySegments,
        request.certificateTemplateBodyText || matchingTemplate?.bodyText
      ),
      certificateTemplateCustomTexts: normalizeTemplateCustomTexts(request.certificateTemplateCustomTexts || matchingTemplate?.customTexts),
      certificateTemplateCustomImages: normalizeTemplateCustomImages(request.certificateTemplateCustomImages || matchingTemplate?.customImages),
      certificateTemplateImageUrl: request.certificateTemplateImageUrl || matchingTemplate?.templateImageUrl || "",
      certificateTemplateImageDataUrl: request.certificateTemplateImageDataUrl || matchingTemplate?.templateImageDataUrl || "",
      certificateTemplateStoragePath: request.certificateTemplateStoragePath || matchingTemplate?.storagePath || "",
      certificateTemplatePositions: normalizeCertificateTemplatePositions(request.certificateTemplatePositions || matchingTemplate?.positions),
      notes: request.notes || "",
      level: requestLevel || matchingTemplate?.level || "No aplica",
      group: requestGroup,
      teacherName: request.teacherName || request.teacherSignerName || "",
      schedule: request.schedule || "",
      printedQuantity: resolvedPrintedQuantity,
      digitalQuantity: resolvedDigitalQuantity,
      principalSignerId: matchingPrincipalSigner?.id || request.principalSignerId || "",
      principalSignerName: matchingPrincipalSigner?.name || request.principalSignerName || request.certificateDirectorName || request.academicDirector || "",
      principalSignerRole: matchingPrincipalSigner?.role || request.principalSignerRole || "Principal",
      principalSignatureUrl: matchingPrincipalSigner?.signatureUrl || request.principalSignatureUrl || "",
      principalSignatureDataUrl: matchingPrincipalSigner?.signatureDataUrl || request.principalSignatureDataUrl || "",
      teacherSignerId: matchingTeacherSigner?.id || request.teacherSignerId || "",
      teacherSignerName: matchingTeacherSigner?.name || request.teacherSignerName || request.teacherName || "",
      teacherSignerRole: matchingTeacherSigner?.role || request.teacherSignerRole || "Teacher",
      teacherSignatureUrl: matchingTeacherSigner?.signatureUrl || request.teacherSignatureUrl || "",
      teacherSignatureDataUrl: matchingTeacherSigner?.signatureDataUrl || request.teacherSignatureDataUrl || "",
    });
  }

  async function savePrintRequest(event) {
    event.preventDefault();
    setRequestMessage("");

    const auditUser = getAuditUser();
    const currentRequest = selectedRequest;

    if (!selectedRequestId && !isAdmin) {
      setRequestMessage("Solo los administradores pueden crear solicitudes desde esta vista.");
      return;
    }

    if (selectedRequestId && !canCurrentUserEditRequest(currentRequest)) {
      setRequestMessage("No tienes permisos para modificar esta solicitud.");
      return;
    }

    const selectedProduct =
      products.find((product) => product.id === requestForm.productId) ||
      products.find((product) => isSameText(product.name, currentRequest?.productName)) ||
      (currentRequest?.productName
        ? {
            id: currentRequest.productId || "",
            name: currentRequest.productName,
            category: currentRequest.requestType || requestForm.requestType,
            level: currentRequest.level || requestForm.level,
          }
        : null);
    const automaticPriority = calculateRequestPriority({
      requestDate: requestForm.requestDate,
      dueDate: requestForm.dueDate,
      createdAt: currentRequest?.createdAt,
    });

    if (!selectedProduct) {
      setRequestMessage("Selecciona un producto o servicio del catálogo.");
      return;
    }

    const requestedQuantity = Number(requestForm.requestedQuantity || 0);
    const nextRequestStatus = normalizePrintRequestStatus(requestForm.status);
    const deliveredQuantity = nextRequestStatus === "Entregada"
      ? requestedQuantity
      : Number(requestForm.deliveredQuantity || 0);
    const printedQuantity = Number(requestForm.printedQuantity || 0);
    const digitalQuantity = Number(requestForm.digitalQuantity || 0);
    const resolvedTemplate = findMatchingCertificateTemplate(requestForm, selectedProduct);
    const resolvedPrincipalSigner = findMatchingCertificateSigner(
      requestForm.principalSignerId,
      requestForm.principalSignerName,
      "Principal"
    );
    const resolvedTeacherSigner = findMatchingCertificateSigner(
      requestForm.teacherSignerId,
      requestForm.teacherSignerName || requestForm.teacherName,
      "Teacher"
    );

    if (requestedQuantity <= 0) {
      setRequestMessage("La cantidad solicitada debe ser mayor que cero.");
      return;
    }

    if (deliveredQuantity > requestedQuantity) {
      setRequestMessage("La cantidad entregada no puede ser mayor que la cantidad solicitada.");
      return;
    }

    if (isRequestCertificateLike(requestForm.requestType)) {
      if (printedQuantity + digitalQuantity !== requestedQuantity) {
        setRequestMessage("En certificados y diplomas, impresos + digitales debe coincidir con la cantidad solicitada.");
        return;
      }

      if (!resolvedTemplate?.id || !resolvedTemplate?.templateImageDataUrl) {
        setRequestMessage("Selecciona una plantilla de certificado con imagen base optimizada. Si la plantilla es antigua, edítala y vuelve a subir su imagen.");
        return;
      }

      if (!requestForm.group.trim() || !requestForm.teacherName.trim() || !requestForm.schedule.trim()) {
        setRequestMessage("Para certificados o diplomas indica grupo, maestro y horario.");
        return;
      }

      if (!resolvedPrincipalSigner?.id || !resolvedPrincipalSigner?.signatureUrl) {
        setRequestMessage("Selecciona el firmante principal con firma cargada.");
        return;
      }

      if (!resolvedTeacherSigner?.id || !resolvedTeacherSigner?.signatureUrl) {
        setRequestMessage("Selecciona el teacher con firma cargada.");
        return;
      }
    }

    const nextResponsibleUid = selectedRequestId
      ? (requestForm.responsibleUid || "")
      : "";
    const nextCollaboratorUid = selectedRequestId
      ? (requestForm.collaboratorUid || "")
      : "";
    const nextResponsible = activeUsers.find((person) => getUserUid(person) === nextResponsibleUid) || null;
    const nextSupport = activeUsers.find((person) => getUserUid(person) === nextCollaboratorUid) || null;
    const nextResponsibleName = selectedRequestId
      ? (requestForm.responsibleName || (nextResponsible ? getUserDisplayName(nextResponsible) : ""))
      : "";
    const nextSupportName = selectedRequestId
      ? (requestForm.collaboratorName || (nextSupport ? getUserDisplayName(nextSupport) : ""))
      : "";
    const currentAssignments = normalizePrintRequestAssignments(currentRequest || {});
    const assignmentChanged =
      isAdmin &&
      Boolean(currentRequest) &&
      (
        currentAssignments.assignedUserId !== nextResponsibleUid ||
        currentAssignments.supportUserId !== nextCollaboratorUid
      );

    const basePayload = {
      productId: selectedProduct.id,
      productName: selectedProduct.name || "",
      requestType: requestForm.requestType,
      requesterName: requestForm.requesterName.trim(),
      requesterArea: requestForm.requesterArea.trim(),
      campus: requestForm.campus,
      ...buildCanonicalPrintRequestAssignment(
        nextResponsibleUid,
        nextCollaboratorUid,
        nextResponsibleName,
        nextSupportName
      ),
      responsibleName: nextResponsibleName,
      responsibleEmail: selectedRequestId ? requestForm.responsibleEmail : getUserEmail(nextResponsible),
      collaboratorName: nextSupportName,
      collaboratorEmail: selectedRequestId ? (requestForm.collaboratorEmail || "") : getUserEmail(nextSupport),
      ...(assignmentChanged
        ? {
            assignedAt: serverTimestamp(),
            assignedByUid: auditUser.uid,
            assignedByName: auditUser.name,
            assignedByEmail: auditUser.email,
          }
        : {}),
      priority: automaticPriority || requestForm.priority || "Normal",
      requestedQuantity,
      deliveredQuantity,
      deliveryType: requestForm.deliveryType,
      status: nextRequestStatus,
      statusLabel: nextRequestStatus,
      requestDate: requestForm.requestDate,
      dueDate: requestForm.dueDate,
      certificateIssueDate: requestForm.certificateIssueDate || "",
      certificateTemplateId: resolvedTemplate?.id || requestForm.certificateTemplateId || "",
      certificateTemplateName: resolvedTemplate?.name || requestForm.certificateTemplateName || "",
      certificateTemplateLevel: resolvedTemplate?.level || requestForm.certificateTemplateLevel || "",
      certificateTemplateProgramName: resolvedTemplate?.programName || requestForm.certificateTemplateProgramName || "",
      certificateTemplateAudience: resolvedTemplate?.audience || requestForm.certificateTemplateAudience || "",
      certificateTemplateBodyText: getCertificateBodyTextFromSegments(
        resolvedTemplate?.bodySegments || requestForm.certificateTemplateBodySegments,
        resolvedTemplate?.bodyText || requestForm.certificateTemplateBodyText
      ),
      certificateTemplateBodySegments: normalizeCertificateBodySegments(
        resolvedTemplate?.bodySegments || requestForm.certificateTemplateBodySegments,
        resolvedTemplate?.bodyText || requestForm.certificateTemplateBodyText
      ),
      certificateTemplateCustomTexts: normalizeTemplateCustomTexts(resolvedTemplate?.customTexts || requestForm.certificateTemplateCustomTexts),
      certificateTemplateCustomImages: normalizeTemplateCustomImages(resolvedTemplate?.customImages || requestForm.certificateTemplateCustomImages),
      certificateTemplateImageUrl: resolvedTemplate?.templateImageUrl || requestForm.certificateTemplateImageUrl || "",
      certificateTemplateImageDataUrl: resolvedTemplate?.templateImageDataUrl || requestForm.certificateTemplateImageDataUrl || "",
      certificateTemplateStoragePath: resolvedTemplate?.storagePath || requestForm.certificateTemplateStoragePath || "",
      certificateTemplatePositions: normalizeCertificateTemplatePositions(resolvedTemplate?.positions || requestForm.certificateTemplatePositions),
      notes: requestForm.notes || "",
      level: requestForm.level || resolvedTemplate?.level || "No aplica",
      group: requestForm.group.trim(),
      teacherName: requestForm.teacherName.trim(),
      schedule: requestForm.schedule.trim(),
      printedQuantity,
      digitalQuantity,
      principalSignerId: resolvedPrincipalSigner?.id || requestForm.principalSignerId || "",
      principalSignerName: resolvedPrincipalSigner?.name || requestForm.principalSignerName || "",
      principalSignerRole: resolvedPrincipalSigner?.role || requestForm.principalSignerRole || "Principal",
      principalSignatureUrl: resolvedPrincipalSigner?.signatureUrl || requestForm.principalSignatureUrl || "",
      principalSignatureDataUrl: resolvedPrincipalSigner?.signatureDataUrl || requestForm.principalSignatureDataUrl || "",
      teacherSignerId: resolvedTeacherSigner?.id || requestForm.teacherSignerId || "",
      teacherSignerName: resolvedTeacherSigner?.name || requestForm.teacherSignerName || requestForm.teacherName.trim(),
      teacherSignerRole: resolvedTeacherSigner?.role || requestForm.teacherSignerRole || "Teacher",
      teacherSignatureUrl: resolvedTeacherSigner?.signatureUrl || requestForm.teacherSignatureUrl || "",
      teacherSignatureDataUrl: resolvedTeacherSigner?.signatureDataUrl || requestForm.teacherSignatureDataUrl || "",
      students: normalizeRequestStudents(currentRequest?.students || []).map((student) =>
        nextRequestStatus === "Entregada" && student.status !== "Cancelado"
          ? { ...student, status: "Entregado" }
          : student
      ),
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };

    try {
      setSavingRequest(true);

      if (selectedRequestId) {
        const payload = isAdmin
          ? basePayload
          : {
              status: basePayload.status,
              statusLabel: basePayload.statusLabel,
              requestedQuantity: basePayload.requestedQuantity,
              deliveredQuantity: basePayload.deliveredQuantity,
              deliveryType: basePayload.deliveryType,
              notes: basePayload.notes,
              dueDate: basePayload.dueDate,
              certificateIssueDate: basePayload.certificateIssueDate,
              certificateTemplateId: basePayload.certificateTemplateId,
              certificateTemplateName: basePayload.certificateTemplateName,
              certificateTemplateLevel: basePayload.certificateTemplateLevel,
              certificateTemplateProgramName: basePayload.certificateTemplateProgramName,
              certificateTemplateAudience: basePayload.certificateTemplateAudience,
              certificateTemplateBodyText: basePayload.certificateTemplateBodyText,
              certificateTemplateBodySegments: basePayload.certificateTemplateBodySegments,
              certificateTemplateCustomTexts: basePayload.certificateTemplateCustomTexts,
              certificateTemplateCustomImages: basePayload.certificateTemplateCustomImages,
              certificateTemplateImageUrl: basePayload.certificateTemplateImageUrl,
              certificateTemplateImageDataUrl: basePayload.certificateTemplateImageDataUrl,
              certificateTemplateStoragePath: basePayload.certificateTemplateStoragePath,
              certificateTemplatePositions: basePayload.certificateTemplatePositions,
              level: basePayload.level,
              group: basePayload.group,
              teacherName: basePayload.teacherName,
              schedule: basePayload.schedule,
              printedQuantity: basePayload.printedQuantity,
              digitalQuantity: basePayload.digitalQuantity,
              principalSignerId: basePayload.principalSignerId,
              principalSignerName: basePayload.principalSignerName,
              principalSignerRole: basePayload.principalSignerRole,
              principalSignatureUrl: basePayload.principalSignatureUrl,
              principalSignatureDataUrl: basePayload.principalSignatureDataUrl,
              teacherSignerId: basePayload.teacherSignerId,
              teacherSignerName: basePayload.teacherSignerName,
              teacherSignerRole: basePayload.teacherSignerRole,
              teacherSignatureUrl: basePayload.teacherSignatureUrl,
              teacherSignatureDataUrl: basePayload.teacherSignatureDataUrl,
              students: basePayload.students,
              updatedAt: basePayload.updatedAt,
              updatedByUid: basePayload.updatedByUid,
              updatedByName: basePayload.updatedByName,
              updatedByEmail: basePayload.updatedByEmail,
            };

        const fieldChangeSummary = buildFieldChangeDescription(currentRequest, payload);

        const changedToDelivered = basePayload.status === "Entregada" && currentRequest?.status !== "Entregada";
        // Timestamp canónico de entrega en la propia solicitud. Solo al transicionar
        // a "Entregada", para no sobrescribirlo en guardados posteriores.
        const deliveryStamp = changedToDelivered
          ? {
              deliveredAt: serverTimestamp(),
              deliveredByUid: auditUser.uid,
              deliveredByName: auditUser.name,
              deliveredByEmail: auditUser.email,
            }
          : null;
        if (changedToDelivered && isRequestCertificateLike(currentRequest?.requestType)) {
          const freshCertificatesSnapshot = await getDocs(query(
            collection(db, "generatedCertificates"),
            where("requestId", "==", selectedRequestId)
          ));
          const deliveredCertificatesById = new Map();
          freshCertificatesSnapshot.docs.forEach((certificateSnapshot) => {
            deliveredCertificatesById.set(certificateSnapshot.id, {
              id: certificateSnapshot.id,
              ...certificateSnapshot.data(),
            });
          });
          generatedCertificates.forEach((certificate) => {
            const association = getCertificateAssociation(certificate, [currentRequest]);
            if (association.request?.id === selectedRequestId) {
              deliveredCertificatesById.set(certificate.id, certificate);
            }
          });
          const deliveredCertificates = [...deliveredCertificatesById.values()].filter(
            (certificate) => normalizeCertificateStatus(certificate.status) !== "Cancelado"
          );
          const publicDocumentsByCertificate = new Map();
          for (const certificate of deliveredCertificates) {
            publicDocumentsByCertificate.set(
              certificate.id,
              await getExistingPublicValidationDocuments(certificate)
            );
          }
          const batch = writeBatch(db);
          batch.update(doc(db, "printRequests", selectedRequestId), deliveryStamp ? { ...payload, ...deliveryStamp } : payload);
          addCertificateHistoryUpserts(
            batch,
            { ...currentRequest, ...basePayload },
            basePayload.students,
            auditUser,
            "Entregado",
            [],
            deliveredCertificates
          );
          deliveredCertificates.forEach((certificate) => {
              const deliveredPayload = {
                status: "Entregado",
                deliveredAt: serverTimestamp(),
                deliveredByUid: auditUser.uid,
                deliveredByName: auditUser.name,
                deliveredByEmail: auditUser.email,
                updatedAt: serverTimestamp(),
                updatedByUid: auditUser.uid,
                updatedByName: auditUser.name,
                updatedByEmail: auditUser.email,
              };
              batch.update(doc(db, "generatedCertificates", certificate.id), deliveredPayload);
              (publicDocumentsByCertificate.get(certificate.id) || []).forEach((validationDocument) => {
                batch.set(doc(db, "publicCertificateValidations", validationDocument.id), {
                  status: "Entregado",
                  updatedAt: serverTimestamp(),
                }, { merge: true });
              });
            });
          await batch.commit();
        } else {
          await updateDoc(doc(db, "printRequests", selectedRequestId), deliveryStamp ? { ...payload, ...deliveryStamp } : payload);
        }
        await createPrintshopLog({
          type: "REQUEST_UPDATED",
          module: "requests",
          title: "Solicitud de imprenta actualizada",
          description: fieldChangeSummary
            ? `Se actualizó la solicitud ${currentRequest?.folio || selectedRequestId}. ${fieldChangeSummary}.`
            : `Se actualizó la solicitud ${currentRequest?.folio || selectedRequestId}.`,
          referenceType: "request",
          referenceId: selectedRequestId,
          requestId: selectedRequestId,
          requestFolio: currentRequest?.folio || "",
          productId: selectedProduct.id,
          productName: selectedProduct.name || "",
          campus: basePayload.campus || "",
          level: basePayload.level || "",
        });
        setRequestMessage("Solicitud actualizada correctamente.");
      } else {
        if (!requestForm.requesterName.trim() || !requestForm.requesterArea.trim()) {
          setRequestMessage("Indica solicitante y área solicitante.");
          setSavingRequest(false);
          return;
        }

        const newRequestFolio = buildRequestFolio(requestForm.requestType);
        const creationPayload = {
          ...basePayload,
          folio: newRequestFolio,
          createdByUid: auditUser.uid,
          createdByName: auditUser.name,
          createdByEmail: auditUser.email,
        };
        delete creationPayload.updatedAt;
        delete creationPayload.assignedAt;
        const creationResult = await createPrintRequestWithAssignment(creationPayload);
        await createPrintshopLog({
          type: "REQUEST_CREATED",
          module: "requests",
          title: "Solicitud de imprenta creada",
          description: `Se creó la solicitud ${newRequestFolio}.`,
          referenceType: "request",
          referenceId: creationResult.requestId,
          requestId: creationResult.requestId,
          requestFolio: newRequestFolio,
          productId: selectedProduct.id,
          productName: selectedProduct.name || "",
          campus: basePayload.campus || "",
          level: basePayload.level || "",
        });
        setRequestForm(requestFormInitialState);
        setRequestMessage("Solicitud creada correctamente.");
      }
    } catch (error) {
      console.error("No se pudo guardar la solicitud de imprenta:", error);
      const isPermissionError = error?.code === "permission-denied";
      setRequestMessage(
        isPermissionError
          ? "No tienes permisos para guardar estos cambios en la solicitud. Revisa tu asignación con un administrador."
          : `No se pudo guardar la solicitud: ${error?.message || "error desconocido"}.`
      );
    } finally {
      setSavingRequest(false);
    }
  }

  async function markRequestInProduction(request) {
    if (
      !request?.id ||
      request.status !== "Solicitud recibida" ||
      !canCurrentUserEditRequest(request)
    ) {
      return;
    }

    const auditUser = getAuditUser();

    try {
      await updateDoc(doc(db, "printRequests", request.id), {
        status: "En producción",
        viewedAt: serverTimestamp(),
        productionStartedAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });

      await createPrintshopLog({
        type: "REQUEST_UPDATED",
        module: "requests",
        title: "Solicitud enviada a producción",
        description: `Se generaron folios o códigos QR para la solicitud ${request.folio || request.id}.`,
        referenceType: "request",
        referenceId: request.id,
        requestId: request.id,
        requestFolio: request.folio || "",
        productId: request.productId || "",
        productName: request.productName || "",
        campus: request.campus || "",
        level: request.level || "",
      });
    } catch (error) {
      console.error("No se pudo cambiar la solicitud a producción:", error);
    }
  }

  async function markRequestReadyForDelivery(request, reason = "Certificados preparados para impresión") {
    if (
      !request?.id ||
      ["Entregada", "Cancelada"].includes(request.status) ||
      !canCurrentUserEditRequest(request)
    ) {
      return;
    }

    const auditUser = getAuditUser();
    const readyForDeliveryAt = new Date(Date.now() + REQUEST_READY_FOR_DELIVERY_DELAY_MS).toISOString();

    try {
      await updateDoc(doc(db, "printRequests", request.id), {
        status: "En producción",
        statusLabel: "En producción",
        printPdfOpenedAt: serverTimestamp(),
        readyForDeliveryAt,
        readyForDeliveryDelayMinutes: 60,
        productionStartedAt: request.productionStartedAt || serverTimestamp(),
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });

      await createPrintshopLog({
        type: "REQUEST_UPDATED",
        module: "requests",
        title: "Entrega de certificados programada",
        description: `${reason}; la solicitud ${request.folio || request.id} quedará lista para entrega una hora después.`,
        referenceType: "request",
        referenceId: request.id,
        requestId: request.id,
        requestFolio: request.folio || "",
        productId: request.productId || "",
        productName: request.productName || "",
        campus: request.campus || "",
        level: request.level || "",
      });
    } catch (error) {
      console.error("No se pudo programar la solicitud como lista para entrega:", error);
    }
  }

  function canCurrentUserManageRequestStudents(request = selectedRequest) {
    return Boolean(
      request &&
      selectedRequestId &&
      isRequestCertificateLike(request.requestType) &&
      normalizePrintRequestStatus(request.status) !== "Entregada" &&
      canCurrentUserEditRequest(request)
    );
  }

  function canCurrentUserAddPeopleAfterClosure(request = selectedRequest) {
    return Boolean(
      request &&
      selectedRequestId &&
      isRequestCertificateLike(request.requestType) &&
      normalizePrintRequestStatus(request.status) !== "Entregada" &&
      canCurrentUserEditRequest(request)
    );
  }

  // ID canónico del documento en publicCertificateValidations.
  // Todos los flujos (generar folio, descargar PDF, entregar, cancelar) deben
  // usar esta clave para no crear documentos públicos duplicados del mismo
  // certificado. Se basa en validationCode porque es estable, único y es la
  // clave que la validación pública consulta por getDoc directo.
  function getRequestStudentValidationId(request, student) {
    return sanitizeGeneratedCertificateId(
      student.validationCode ||
        student.certificateFolio ||
        `${request.id}-${student.id}`
    );
  }

  function buildRequestStudentPublicValidationPayload(request, student) {
    return buildPublicCertificateValidationPayload(
      {
        folio: student.certificateFolio,
        validationCode: student.validationCode,
        validationUrl:
          student.validationUrl || buildValidationUrl(student.validationCode),
        studentName: student.name,
        campus: request.campus || "Sin plantel",
        requestId: request.id,
        requestFolio: request.folio || "",
        requestType: request.requestType || "Certificado",
        productName: request.productName || "",
        level: request.level || "No aplica",
        programName:
          request.certificateTemplateProgramName ||
          getCertificateTrackLabel(request),
        templateName:
          request.certificateTemplateName ||
          "Plantilla no especificada",
        issueDate: getCertificateIssueDate(request),
        teacherName:
          request.teacherSignerName ||
          request.teacherName ||
          "",
        status: "Generado",
      },
      {
        generationMode: "request",
      }
    );
  }

  function getCertificateRecordId(request, student, certificates = generatedCertificates) {
    const existing = certificates.find((certificate) =>
      certificate.requestId === request.id &&
      (certificate.studentId === student.id || certificate.validationCode === student.validationCode)
    );
    return existing?.id || sanitizeGeneratedCertificateId(`${request.id}-${student.id}`);
  }

  function buildGeneratedCertificateFromStudent(request, student, auditUser, status, certificates = generatedCertificates) {
    const existing = certificates.find((certificate) =>
      certificate.requestId === request.id &&
      (certificate.studentId === student.id || certificate.validationCode === student.validationCode)
    );
    const issueDate = getCertificateIssueDate(request);
    const issueYear = getYearFromDateString(issueDate) || String(new Date().getFullYear());
    return {
      folio: student.certificateFolio,
      validationCode: student.validationCode,
      validationUrl: student.validationUrl || buildValidationUrl(student.validationCode),
      studentId: student.id,
      studentName: student.name,
      studentDeliveryType: student.deliveryType || "Impreso",
      campus: request.campus || "Sin plantel",
      group: request.group || "",
      requestId: request.id,
      requestFolio: request.folio || "",
      requestType: request.requestType || "Certificado",
      productId: request.productId || "",
      productName: request.productName || "",
      assignedUserId: normalizePrintRequestAssignments(request).assignedUserId,
      supportUserId: normalizePrintRequestAssignments(request).supportUserId,
      responsibleUid: request.responsibleUid || "",
      responsibleName: request.responsibleName || "",
      responsibleEmail: request.responsibleEmail || "",
      level: request.level || "No aplica",
      programName: request.certificateTemplateProgramName || getCertificateTrackLabel(request),
      templateId: request.certificateTemplateId || "",
      templateName: request.certificateTemplateName || "Plantilla no especificada",
      issueDate,
      issueYear,
      generatedYear: issueYear,
      principalName: request.principalSignerName || "",
      teacherName: request.teacherSignerName || request.teacherName || "",
      status,
      pdfFileName: existing?.pdfFileName || "",
      ...(existing?.pdfUrl ? { pdfUrl: existing.pdfUrl } : {}),
      ...(existing?.pdfStoragePath ? { pdfStoragePath: existing.pdfStoragePath } : {}),
      ...(existing?.pdfPageVersion ? { pdfPageVersion: existing.pdfPageVersion } : {}),
      ...(existing?.pdfPageWidthPt ? { pdfPageWidthPt: existing.pdfPageWidthPt } : {}),
      ...(existing?.pdfPageHeightPt ? { pdfPageHeightPt: existing.pdfPageHeightPt } : {}),
      generatedAt: existing?.generatedAt || student.certificateGeneratedAt || student.generatedAt || serverTimestamp(),
      generatedByUid: existing?.generatedByUid || auditUser.uid,
      generatedByName: existing?.generatedByName || auditUser.name,
      generatedByEmail: existing?.generatedByEmail || auditUser.email,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };
  }

  function addCertificateHistoryUpserts(
    batch,
    request,
    students,
    auditUser,
    forcedStatus = "",
    pendingCertificateIds = [],
    knownCertificates = generatedCertificates
  ) {
    const studentsWithFolios = normalizeRequestStudents(students).filter(
      (student) => student.certificateFolio && student.validationCode
    );
    const pendingIds = new Set(pendingCertificateIds);
    const generatedStudents = studentsWithFolios.filter((student) => {
      const certificateId = getCertificateRecordId(request, student, knownCertificates);
      return pendingIds.has(certificateId) || knownCertificates.some((certificate) =>
        certificate.id === certificateId ||
        certificate.requestId === request.id && (
          certificate.studentId === student.id ||
          certificate.validationCode === student.validationCode
        )
      );
    });
    if (generatedStudents.length === 0) return;
    const requestDelivered = normalizeCertificateStatus(forcedStatus || request.status) === "Entregado";
    const activeStatuses = generatedStudents.map((student) =>
      normalizeCertificateStatus(student.status) === "Cancelado" ? "Cancelado" : requestDelivered ? "Entregado" : "Generado"
    );
    const loteStatus = activeStatuses.every((status) => status === activeStatuses[0])
      ? activeStatuses[0]
      : "Mixto";

    batch.set(doc(db, "certificateHistoryBatches", request.id), {
      requestId: request.id,
      loteId: request.id,
      requestFolio: request.folio || "",
      certificateIds: generatedStudents.map((student) => getCertificateRecordId(request, student, knownCertificates)),
      certificateCount: generatedStudents.length,
      status: loteStatus,
      campus: request.campus || "",
      group: request.group || "",
      level: request.level || "No aplica",
      templateId: request.certificateTemplateId || "",
      templateName: request.certificateTemplateName || "",
      teacherId: request.teacherSignerId || request.teacherId || "",
      teacherName: request.teacherSignerName || request.teacherName || "",
      groupSchedule: request.groupSchedule || request.schedule || "",
      issueDate: getCertificateIssueDate(request),
      generatedAt: getOriginalCertificateGenerationValue(generatedStudents, request),
      responsibleUid: request.responsibleUid || "",
      collaboratorUid: request.collaboratorUid || "",
      assignedUserId: normalizePrintRequestAssignments(request).assignedUserId,
      supportUserId: normalizePrintRequestAssignments(request).supportUserId,
      createdAt: request.createdAt || serverTimestamp(),
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    }, { merge: true });

    generatedStudents.forEach((student, index) => {
      const certificateId = getCertificateRecordId(request, student, knownCertificates);
      const payload = buildGeneratedCertificateFromStudent(
        request,
        student,
        auditUser,
        activeStatuses[index],
        knownCertificates
      );
      batch.set(doc(db, "generatedCertificates", certificateId), payload, { merge: true });
      batch.set(doc(db, "publicCertificateValidations", getRequestStudentValidationId(request, student)), buildPublicCertificateValidationPayload(payload, {
        status: activeStatuses[index],
        generationMode: "request",
        updatedAt: serverTimestamp(),
      }), { merge: true });
    });
  }

  function addHistoryBatchStatusWrite(batch, request, changedCertificateId, nextStatus, auditUser) {
    if (!request?.id) return;
    const statuses = generatedCertificates
      .filter((certificate) => certificate.requestId === request.id)
      .map((certificate) => certificate.id === changedCertificateId ? nextStatus : certificate.status);
    const loteStatus = statuses.length > 0 && statuses.every((status) => status === statuses[0])
      ? statuses[0]
      : "Mixto";
    batch.set(doc(db, "certificateHistoryBatches", request.id), {
      requestId: request.id,
      loteId: request.id,
      requestFolio: request.folio || "",
      status: loteStatus,
      certificateCount: statuses.length,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    }, { merge: true });
  }

  function addGeneratedCertificateRegistration(batch, request, students, auditUser, forcedStatus = "") {
    const studentsWithFolios = normalizeRequestStudents(students).filter(
      (student) => student.certificateFolio && student.validationCode
    );

    if (studentsWithFolios.length === 0) return [];

    const requestDelivered = normalizeCertificateStatus(forcedStatus || request.status) === "Entregado";
    const registeredStudents = [];
    const registeredIds = [];
    const registeredStatuses = [];

    studentsWithFolios.forEach((student) => {
      const certificateId = getCertificateRecordId(request, student);
      const existing = generatedCertificates.find(
        (certificate) =>
          certificate.id === certificateId ||
          certificate.validationCode === student.validationCode
      );

      // No revivir certificados eliminados de forma lógica.
      if (existing?.deleted === true) return;

      const status =
        normalizeCertificateStatus(student.status) === "Cancelado"
          ? "Cancelado"
          : existing?.status === "Entregado" || requestDelivered
            ? "Entregado"
            : "Generado";

      const certificatePayload = buildGeneratedCertificateFromStudent(
        request,
        student,
        auditUser,
        status
      );

      batch.set(doc(db, "generatedCertificates", certificateId), certificatePayload, { merge: true });
      batch.set(
        doc(db, "publicCertificateValidations", getRequestStudentValidationId(request, student)),
        buildPublicCertificateValidationPayload(certificatePayload, {
          publishedAt: serverTimestamp(),
        }),
        { merge: true }
      );

      registeredStudents.push(student);
      registeredIds.push(certificateId);
      registeredStatuses.push(status);
    });

    if (registeredIds.length === 0) return [];

    const loteStatus = registeredStatuses.every((status) => status === registeredStatuses[0])
      ? registeredStatuses[0]
      : "Mixto";

    batch.set(doc(db, "certificateHistoryBatches", request.id), {
      requestId: request.id,
      loteId: request.id,
      requestFolio: request.folio || "",
      certificateIds: registeredIds,
      certificateCount: registeredIds.length,
      status: loteStatus,
      campus: request.campus || "",
      group: request.group || "",
      level: request.level || "No aplica",
      templateId: request.certificateTemplateId || "",
      templateName: request.certificateTemplateName || "",
      teacherId: request.teacherSignerId || request.teacherId || "",
      teacherName: request.teacherSignerName || request.teacherName || "",
      groupSchedule: request.groupSchedule || request.schedule || "",
      issueDate: getCertificateIssueDate(request),
      generatedAt: getOriginalCertificateGenerationValue(registeredStudents, request),
      responsibleUid: request.responsibleUid || "",
      collaboratorUid: request.collaboratorUid || "",
      assignedUserId: normalizePrintRequestAssignments(request).assignedUserId,
      supportUserId: normalizePrintRequestAssignments(request).supportUserId,
      createdAt: request.createdAt || serverTimestamp(),
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    }, { merge: true });

    return registeredIds;
  }

  async function updateSelectedRequestStudents(nextStudents, successMessage = "Lista de alumnos actualizada.") {
    const currentRequest = selectedRequest;

    if (!currentRequest || !selectedRequestId) {
      setRequestMessage("Selecciona primero una solicitud de certificado o diploma.");
      return;
    }

    if (!isRequestCertificateLike(currentRequest.requestType)) {
      setRequestMessage("La lista de alumnos solo aplica para certificados y diplomas.");
      return;
    }

    if (!canCurrentUserManageRequestStudents(currentRequest)) {
      setRequestMessage("No tienes permisos para modificar la lista de alumnos de esta solicitud.");
      return;
    }

    const auditUser = getAuditUser();
    const normalizedStudents = normalizeRequestStudents(nextStudents);

    try {
      setSavingStudents(true);
      setRequestMessage("");

      const hasGeneratedFolios = normalizedStudents.some(
        (student) => student.qrGenerated === true || Boolean(student.certificateFolio)
      );
      const shouldMoveToProduction =
        hasGeneratedFolios &&
        ["Solicitud recibida", "Datos incompletos", "En revisión", "Aprobada"].includes(currentRequest.status);
      const deliveryCounts = getStudentDeliveryCounts(normalizedStudents);
      const deliveryType = deliveryCounts.printed > 0 && deliveryCounts.digital > 0
        ? "Ambas"
        : deliveryCounts.digital > 0
          ? "Digital"
          : "Impresa";

      const requestRef = doc(db, "printRequests", selectedRequestId);
      const batch = writeBatch(db);

      batch.update(requestRef, {
        students: normalizedStudents,
        requestedQuantity: deliveryCounts.total,
        printedQuantity: deliveryCounts.printed,
        digitalQuantity: deliveryCounts.digital,
        deliveryType,
        ...(shouldMoveToProduction
          ? {
              status: "En producción",
              statusLabel: "En producción",
              productionStartedAt: currentRequest.productionStartedAt || serverTimestamp(),
            }
          : {}),
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });

      addGeneratedCertificateRegistration(
        batch,
        { ...currentRequest, status: shouldMoveToProduction ? "En producción" : currentRequest.status },
        normalizedStudents,
        auditUser
      );

      await batch.commit();
      setRequestMessage(successMessage);
      return true;
    } catch (error) {
      console.error(
        "No se pudo registrar la lista de alumnos ni los certificados. Colecciones: printRequests, generatedCertificates, publicCertificateValidations, certificateHistoryBatches.",
        error
      );
      setRequestMessage(
        "No se pudieron registrar los certificados en el historial ni habilitar la validación por QR. Revisa tus permisos o la conexión. No se marcó como completado."
      );
      return false;
    } finally {
      setSavingStudents(false);
    }
  }

  async function registerGeneratedCertificate({
    request,
    student,
    certificateTemplate,
    principalName,
    teacherName,
    fileName,
    pdfUrl = "",
    pdfStoragePath = "",
  }) {
    if (!request?.id || !student?.id) {
      throw new Error("No se encontró la solicitud o el alumno para registrar el certificado.");
    }

    if (!student.certificateFolio || !student.validationCode) {
      throw new Error("Primero genera folio y QR para este alumno.");
    }

    if (!pdfStoragePath && !pdfUrl) {
      throw new Error("El PDF no se almacenó en Storage; no se registrará un historial sin archivo original.");
    }

    const auditUser = getAuditUser();
    const nowIso = new Date().toISOString();
    const certificateId = getCertificateRecordId(request, student);
    const existingCertificate = generatedCertificates.find(
      (certificate) => certificate.id === certificateId || certificate.validationCode === student.validationCode
    );
    const nextStatus =
      existingCertificate?.status === "Entregado" ? "Entregado" : "Generado";
    const normalizedStudents = normalizeRequestStudents(request.students || []);
    const nextStudents = normalizedStudents.map((currentStudent) =>
      currentStudent.id === student.id
        ? {
            ...currentStudent,
            status: nextStatus,
            certificateRecordId: certificateId,
            certificateGeneratedAt: currentStudent.certificateGeneratedAt || currentStudent.generatedAt || existingCertificate?.generatedAt || nowIso,
            certificateGeneratedByUid: auditUser.uid,
            certificateGeneratedByName: auditUser.name,
            certificateGeneratedByEmail: auditUser.email,
          }
        : currentStudent
    );

    const programName =
      certificateTemplate?.programName ||
      request.certificateTemplateProgramName ||
      getCertificateTrackLabel(request);
    const templateName =
      certificateTemplate?.name || request.certificateTemplateName || "Plantilla no especificada";

    const issueDate = getCertificateIssueDate(request);
    const issueYear = getYearFromDateString(issueDate) || String(new Date().getFullYear());

    const certificatePayload = {
      folio: student.certificateFolio,
      validationCode: student.validationCode,
      validationUrl: student.validationUrl || buildValidationUrl(student.validationCode),
      studentId: student.id,
      studentName: student.name,
      studentDeliveryType: student.deliveryType || "Impreso",
      campus: request.campus || "Sin plantel",
      group: request.group || "",
      requestId: request.id,
      requestFolio: request.folio || "",
      requestType: request.requestType || "Certificado",
      productId: request.productId || "",
      productName: request.productName || "",
      assignedUserId: normalizePrintRequestAssignments(request).assignedUserId,
      supportUserId: normalizePrintRequestAssignments(request).supportUserId,
      responsibleUid: request.responsibleUid || "",
      responsibleName: request.responsibleName || "",
      responsibleEmail: request.responsibleEmail || "",
      level: request.level || "No aplica",
      programName,
      templateId: request.certificateTemplateId || certificateTemplate?.id || "",
      templateName,
      issueDate,
      issueYear,
      generatedYear: issueYear,
      principalName: principalName || request.principalSignerName || "",
      teacherName: teacherName || request.teacherSignerName || request.teacherName || "",
      status: nextStatus,
      pdfFileName: fileName || "",
      pdfUrl: pdfUrl || existingCertificate?.pdfUrl || "",
      pdfStoragePath: pdfStoragePath || existingCertificate?.pdfStoragePath || "",
      ...(pdfStoragePath || pdfUrl ? {
        pdfSavedAt: serverTimestamp(),
        pdfPageVersion: CERTIFICATE_PAGE_VERSION,
        pdfPageWidthPt: CERTIFICATE_PAGE.widthPt,
        pdfPageHeightPt: CERTIFICATE_PAGE.heightPt,
        pdfPageOrientation: CERTIFICATE_PAGE.orientation,
      } : {}),
      generatedAt: existingCertificate?.generatedAt || student.certificateGeneratedAt || student.generatedAt || serverTimestamp(),
      generatedByUid: existingCertificate?.generatedByUid || auditUser.uid,
      generatedByName: existingCertificate?.generatedByName || auditUser.name,
      generatedByEmail: existingCertificate?.generatedByEmail || auditUser.email,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };

    const publicCertificatePayload = buildPublicCertificateValidationPayload(certificatePayload, {
      publishedAt: serverTimestamp(),
    });

    const batch = writeBatch(db);
    addCertificateHistoryUpserts(batch, request, nextStudents, auditUser, "", [certificateId]);
    batch.set(doc(db, "generatedCertificates", certificateId), certificatePayload, { merge: true });
    batch.set(doc(db, "publicCertificateValidations", getRequestStudentValidationId(request, student)), publicCertificatePayload, { merge: true });
    batch.update(doc(db, "printRequests", request.id), {
      students: nextStudents,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    });

    await batch.commit();
    await createPrintshopLog({
      type: "CERTIFICATE_GENERATED",
      module: "certificates",
      title: "Certificado generado",
      description: `Se generó el certificado de ${student.name}.`,
      referenceType: "certificate",
      referenceId: certificateId,
      requestId: request.id,
      requestFolio: request.folio || "",
      certificateId,
      certificateFolio: student.certificateFolio,
      validationCode: student.validationCode,
      studentName: student.name,
      productId: request.productId || "",
      productName: request.productName || "",
      campus: request.campus || "",
      level: request.level || "",
    });
    setRequestMessage(`Certificado ${student.certificateFolio} registrado en el historial.`);
  }

  async function registerStandaloneGeneratedCertificate({
    request,
    student,
    certificateTemplate,
    principalName,
    teacherName,
    fileName,
    pdfUrl = "",
    pdfStoragePath = "",
  }) {
    if (!request?.id || !student?.id) {
      throw new Error("No se encontro la informacion para registrar el certificado individual.");
    }

    if (!student.certificateFolio || !student.validationCode) {
      throw new Error("Primero prepara folio y QR para este certificado.");
    }

    if (!pdfStoragePath && !pdfUrl) {
      throw new Error("El PDF no se almacenó en Storage; no se registrará un certificado sin archivo original.");
    }

    const auditUser = getAuditUser();
    const certificateId = sanitizeGeneratedCertificateId(
      student.validationCode || student.certificateFolio || `${request.id}-${student.id}`
    );
    const existingCertificate = generatedCertificates.find(
      (certificate) => certificate.id === certificateId || certificate.validationCode === student.validationCode
    );
    const nextStatus = existingCertificate?.status === "Entregado" ? "Entregado" : "Generado";
    const programName =
      certificateTemplate?.programName ||
      request.certificateTemplateProgramName ||
      getCertificateTrackLabel(request);
    const templateName =
      certificateTemplate?.name || request.certificateTemplateName || "Plantilla no especificada";
    const issueDate = getCertificateIssueDate(request);
    const issueYear = getYearFromDateString(issueDate) || String(new Date().getFullYear());

    const certificatePayload = {
      folio: student.certificateFolio,
      validationCode: student.validationCode,
      validationUrl: student.validationUrl || buildValidationUrl(student.validationCode),
      studentId: student.id,
      studentName: student.name,
      studentDeliveryType: student.deliveryType || "Impreso",
      campus: request.campus || "Sin plantel",
      group: request.group || "",
      requestId: "",
      requestFolio: request.folio || "Individual",
      generationMode: "individual",
      requestType: request.requestType || "Certificado",
      productId: request.productId || "",
      productName: request.productName || "Certificado individual",
      responsibleUid: auditUser.uid,
      responsibleName: auditUser.name,
      responsibleEmail: auditUser.email,
      level: request.level || "No aplica",
      programName,
      templateId: request.certificateTemplateId || certificateTemplate?.id || "",
      templateName,
      issueDate,
      issueYear,
      generatedYear: issueYear,
      principalName: principalName || request.principalSignerName || "",
      teacherName: teacherName || request.teacherSignerName || request.teacherName || "",
      status: nextStatus,
      pdfFileName: fileName || "",
      pdfUrl: pdfUrl || existingCertificate?.pdfUrl || "",
      pdfStoragePath: pdfStoragePath || existingCertificate?.pdfStoragePath || "",
      ...(pdfStoragePath || pdfUrl ? {
        pdfSavedAt: serverTimestamp(),
        pdfPageVersion: CERTIFICATE_PAGE_VERSION,
        pdfPageWidthPt: CERTIFICATE_PAGE.widthPt,
        pdfPageHeightPt: CERTIFICATE_PAGE.heightPt,
        pdfPageOrientation: CERTIFICATE_PAGE.orientation,
      } : {}),
      generatedAt: existingCertificate?.generatedAt || student.certificateGeneratedAt || student.generatedAt || serverTimestamp(),
      generatedByUid: existingCertificate?.generatedByUid || auditUser.uid,
      generatedByName: existingCertificate?.generatedByName || auditUser.name,
      generatedByEmail: existingCertificate?.generatedByEmail || auditUser.email,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };

    const batch = writeBatch(db);
    batch.set(doc(db, "generatedCertificates", certificateId), certificatePayload, { merge: true });
    batch.set(
      doc(db, "publicCertificateValidations", certificateId),
      buildPublicCertificateValidationPayload(certificatePayload, {
        publishedAt: serverTimestamp(),
      }),
      { merge: true }
    );

    await batch.commit();
    await createPrintshopLog({
      type: "CERTIFICATE_GENERATED",
      module: "certificates",
      title: "Certificado individual generado",
      description: `Se genero un certificado individual para ${student.name}.`,
      referenceType: "certificate",
      referenceId: certificateId,
      certificateId,
      certificateFolio: student.certificateFolio,
      validationCode: student.validationCode,
      studentName: student.name,
      productName: request.productName || "Certificado individual",
      campus: request.campus || "",
      level: request.level || "",
    });
    return { certificateId, certificatePayload };
  }

  async function updateGeneratedCertificateStatus(certificate, nextStatus) {
    const normalizedNextStatus = normalizeCertificateStatus(nextStatus, "");
    if (!certificate?.id || !generatedCertificateStatuses.includes(normalizedNextStatus)) return;
    nextStatus = normalizedNextStatus;

    const auditUser = getAuditUser();
    const nowIso = new Date().toISOString();
    const request = findCertificateRequest(certificate, printRequests);
    const publicValidationDocuments = await getExistingPublicValidationDocuments(certificate);
    const batch = writeBatch(db);
    const certificateRef = doc(db, "generatedCertificates", certificate.id);
    const statusPayload = {
      status: nextStatus,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };

    if (nextStatus === "Entregado") {
      statusPayload.deliveredAt = serverTimestamp();
      statusPayload.deliveredByUid = auditUser.uid;
      statusPayload.deliveredByName = auditUser.name;
      statusPayload.deliveredByEmail = auditUser.email;
    }

    if (nextStatus === "Cancelado") {
      statusPayload.cancelledAt = serverTimestamp();
      statusPayload.cancelledByUid = auditUser.uid;
      statusPayload.cancelledByName = auditUser.name;
      statusPayload.cancelledByEmail = auditUser.email;
    }

    batch.update(certificateRef, statusPayload);
    addHistoryBatchStatusWrite(batch, request, certificate.id, nextStatus, auditUser);

    const publicCertificateIds = publicValidationDocuments.length > 0
      ? publicValidationDocuments.map((validationDocument) => validationDocument.id)
      : [sanitizeGeneratedCertificateId(certificate.validationCode || certificate.id || certificate.folio)];
    publicCertificateIds.forEach((publicCertificateId) => {
      batch.set(
        doc(db, "publicCertificateValidations", publicCertificateId),
        buildPublicCertificateValidationPayload(certificate, {
          status: nextStatus,
          updatedAt: serverTimestamp(),
        }),
        { merge: true }
      );
    });

    if (request) {
      const nextStudents = normalizeRequestStudents(request.students || []).map((student) => {
        const matchesStudent =
          student.id === certificate.studentId ||
          student.certificateRecordId === certificate.id ||
          student.certificateFolio === certificate.folio;

        if (!matchesStudent) return student;

        const nextStudent = {
          ...student,
          status: nextStatus,
          certificateRecordId: certificate.id,
        };

        if (nextStatus === "Entregado") {
          nextStudent.certificateDeliveredAt = nowIso;
          nextStudent.certificateDeliveredByUid = auditUser.uid;
          nextStudent.certificateDeliveredByName = auditUser.name;
          nextStudent.certificateDeliveredByEmail = auditUser.email;
        }

        if (nextStatus === "Cancelado") {
          nextStudent.certificateCancelledAt = nowIso;
          nextStudent.certificateCancelledByUid = auditUser.uid;
          nextStudent.certificateCancelledByName = auditUser.name;
          nextStudent.certificateCancelledByEmail = auditUser.email;
        }

        return nextStudent;
      });

      batch.update(doc(db, "printRequests", request.id), {
        students: nextStudents,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });
    }

    try {
      setUpdatingGeneratedCertificateId(certificate.id);
      await batch.commit();
      await createPrintshopLog({
        type: nextStatus === "Cancelado" ? "CERTIFICATE_CANCELLED" : "CERTIFICATE_DELIVERED",
        module: "certificates",
        title: nextStatus === "Cancelado" ? "Certificado cancelado" : "Certificado entregado",
        description: `${certificate.studentName || "Alumno"} quedó como ${nextStatus}.`,
        referenceType: "certificate",
        referenceId: certificate.id,
        requestId: certificate.requestId || "",
        requestFolio: certificate.requestFolio || "",
        certificateId: certificate.id,
        certificateFolio: certificate.folio || "",
        validationCode: certificate.validationCode || "",
        studentName: certificate.studentName || "",
        productId: certificate.productId || "",
        productName: certificate.productName || "",
        campus: certificate.campus || "",
        level: certificate.level || "",
      });
    } catch (error) {
      console.error("No se pudo actualizar el estado del certificado:", error);
      setGeneratedCertificatesError("No se pudo actualizar el certificado. Revisa las reglas de Firestore.");
    } finally {
      setUpdatingGeneratedCertificateId(null);
    }
  }

  async function getRequestForGeneratedCertificate(certificate) {
    const loadedRequest = findCertificateRequest(certificate, printRequests);

    if (loadedRequest) return loadedRequest;

    const requestId = getCertificateRequestId(certificate);
    if (!requestId) return null;

    const requestSnapshot = await withCertificateActionTimeout(
      getDoc(doc(db, "printRequests", requestId)),
      "consultar la solicitud"
    );
    return requestSnapshot.exists()
      ? { id: requestSnapshot.id, ...requestSnapshot.data() }
      : null;
  }

  async function getExistingPublicValidationDocuments(certificate) {
    const matches = new Map();
    const candidateIds = [...new Set([
      certificate?.validationCode,
      sanitizeGeneratedCertificateId(certificate?.validationCode),
      certificate?.id,
      certificate?.folio,
    ].map((value) => String(value || "").trim()).filter(Boolean))];

    for (const candidateId of candidateIds) {
      try {
        const snapshot = await getDoc(doc(db, "publicCertificateValidations", candidateId));
        if (snapshot.exists()) matches.set(snapshot.id, { id: snapshot.id, ...snapshot.data() });
      } catch (error) {
        console.warn("[Certificados] No se pudo consultar índice QR", { candidateId, error });
      }
    }

    for (const [field, value] of [
      ["validationCode", certificate?.validationCode],
      ["folio", certificate?.folio],
      ["certificateId", certificate?.id],
    ]) {
      if (!value) continue;
      try {
        const snapshot = await getDocs(query(
          collection(db, "publicCertificateValidations"),
          where(field, "==", value)
        ));
        snapshot.docs.forEach((snapshotDoc) => {
          matches.set(snapshotDoc.id, { id: snapshotDoc.id, ...snapshotDoc.data() });
        });
      } catch (error) {
        console.warn("[Certificados] No se pudo consultar índice QR por campo", { field, value, error });
      }
    }

    return [...matches.values()];
  }

  async function repairCertificateHistoryConsistency() {
    if (!isAdmin) return { synchronized: 0, dated: 0, metadata: 0 };

    const loadedHistory = certificateHistoryBatches.length > 0
      ? certificateHistoryBatches
      : (await getDocs(collection(db, "certificateHistoryBatches"))).docs.map((snapshotDoc) => ({
        id: snapshotDoc.id,
        ...snapshotDoc.data(),
      }));
    const historyById = new Map(loadedHistory.map((history) => [history.id, history]));
    let synchronized = 0;
    let dated = 0;
    let metadata = 0;

    for (let offset = 0; offset < loadedHistory.length; offset += 400) {
      const metadataBatch = writeBatch(db);
      let metadataWrites = 0;

      loadedHistory.slice(offset, offset + 400).forEach((history) => {
        const requestId = getCertificateRequestId(history) || history.id;
        const matchedRequest = printRequests.find((request) => request.id === requestId) || null;
        const historyCertificateIds = new Set(Array.isArray(history.certificateIds) ? history.certificateIds : []);
        const certificates = generatedCertificates.filter((certificate) =>
          certificate.requestId === requestId || historyCertificateIds.has(certificate.id)
        );
        const nextMetadata = getCertificateHistoryMetadata(history, matchedRequest, certificates);
        const patch = {};

        if (!String(history.teacherId || "").trim() && nextMetadata.teacherId) {
          patch.teacherId = nextMetadata.teacherId;
        }
        if (!String(history.teacherName || "").trim() && nextMetadata.teacherName) {
          patch.teacherName = nextMetadata.teacherName;
        }
        if (!String(history.groupSchedule || "").trim() && nextMetadata.groupSchedule) {
          patch.groupSchedule = nextMetadata.groupSchedule;
        }
        if (!toCertificateHistoryDate(history.generatedAt) && toCertificateHistoryDate(nextMetadata.generatedAt)) {
          patch.generatedAt = nextMetadata.generatedAt;
        }

        if (Object.keys(patch).length > 0) {
          metadataBatch.set(doc(db, "certificateHistoryBatches", history.id), patch, { merge: true });
          metadataWrites += 1;
          metadata += 1;
        }
      });

      if (metadataWrites > 0) await metadataBatch.commit();
    }

    for (const request of printRequests) {
      const history = historyById.get(request.id) || null;
      const delivered = normalizeCertificateStatus(request.status) === "Entregado" ||
        normalizeCertificateStatus(history?.status) === "Entregado";
      if (!delivered) continue;

      const historyCertificateIds = new Set(Array.isArray(history?.certificateIds) ? history.certificateIds : []);
      const certificates = generatedCertificates.filter((certificate) => {
        const association = getCertificateAssociation(certificate, [request]);
        return association.request?.id === request.id || historyCertificateIds.has(certificate.id);
      });
      const publicDocuments = new Map();
      for (const certificate of certificates) {
        publicDocuments.set(certificate.id, await getExistingPublicValidationDocuments(certificate));
      }

      const batch = writeBatch(db);
      let writes = 0;
      const currentStudents = Array.isArray(request.students) ? request.students : [];
      const requestPatch = {};
      const nextStudents = currentStudents.map((student) => {
        const status = normalizeCertificateStatus(student?.status, "");
        if (status === "Cancelado" || status === "Entregado") return student;
        synchronized += 1;
        return { ...student, status: "Entregado" };
      });
      if (nextStudents.some((student, index) => student !== currentStudents[index])) {
        requestPatch.students = nextStudents;
      }
      if (normalizeCertificateStatus(request.status) !== "Entregado") {
        requestPatch.status = "Entregada";
        synchronized += 1;
      }
      if (Object.keys(requestPatch).length > 0) {
        batch.update(doc(db, "printRequests", request.id), requestPatch);
        writes += 1;
      }

      certificates.forEach((certificate) => {
        if (normalizeCertificateStatus(certificate.status) !== "Entregado" &&
            normalizeCertificateStatus(certificate.status) !== "Cancelado") {
          batch.update(doc(db, "generatedCertificates", certificate.id), { status: "Entregado" });
          writes += 1;
          synchronized += 1;
        }

        const validationDocuments = publicDocuments.get(certificate.id) || [];
        if (validationDocuments.length === 0) {
          const publicId = sanitizeGeneratedCertificateId(
            certificate.validationCode || certificate.id || certificate.folio
          );
          batch.set(
            doc(db, "publicCertificateValidations", publicId),
            buildPublicCertificateValidationPayload(certificate, { status: "Entregado" }),
            { merge: true }
          );
          writes += 1;
          synchronized += 1;
        } else {
          validationDocuments.forEach((validationDocument) => {
            if (normalizeCertificateStatus(validationDocument.status) !== "Entregado") {
              batch.set(doc(db, "publicCertificateValidations", validationDocument.id), {
                status: "Entregado",
              }, { merge: true });
              writes += 1;
              synchronized += 1;
            }
          });
        }
      });

      const originalGeneratedAt = getOriginalCertificateGenerationValue(
        currentStudents,
        request,
        certificates
      );
      const historyPatch = {};
      if (normalizeCertificateStatus(history?.status) !== "Entregado") historyPatch.status = "Entregado";
      if (!toCertificateDate(history?.generatedAt) && toCertificateDate(originalGeneratedAt)) {
        historyPatch.generatedAt = originalGeneratedAt;
        dated += 1;
      }
      if (Object.keys(historyPatch).length > 0) {
        batch.set(doc(db, "certificateHistoryBatches", request.id), {
          requestId: request.id,
          loteId: request.id,
          ...historyPatch,
        }, { merge: true });
        writes += 1;
      }

      if (writes > 0) await batch.commit();
    }

    return { synchronized, dated, metadata };
  }

  async function persistGeneratedCertificatePdfRepair(certificate, request, pdfSource, regenerated) {
    if (!certificate?.id || !pdfSource?.url || !pdfSource?.storagePath) {
      throw new Error("Faltan referencias estables para guardar la reparación del certificado.");
    }

    const patch = {
      ...(request?.id && certificate.requestId !== request.id ? { requestId: request.id } : {}),
      ...(request?.folio && certificate.requestFolio !== request.folio ? { requestFolio: request.folio } : {}),
      ...(certificate.pdfUrl !== pdfSource.url ? { pdfUrl: pdfSource.url } : {}),
      ...(certificate.pdfStoragePath !== pdfSource.storagePath ? { pdfStoragePath: pdfSource.storagePath } : {}),
      ...(certificate.pdfPath !== pdfSource.storagePath ? { pdfPath: pdfSource.storagePath } : {}),
      ...(regenerated ? {
        pdfPageVersion: CERTIFICATE_PAGE_VERSION,
        pdfPageWidthPt: CERTIFICATE_PAGE.widthPt,
        pdfPageHeightPt: CERTIFICATE_PAGE.heightPt,
        pdfPageOrientation: CERTIFICATE_PAGE.orientation,
        pdfRepairVersion: CERTIFICATE_PAGE_VERSION,
      } : {}),
    };

    if (Object.entries(patch).some(([key, value]) => certificate[key] !== value)) {
      await updateDoc(doc(db, "generatedCertificates", certificate.id), patch);
    }
  }

  async function openOriginalGeneratedCertificate(certificate, buildPdfBlob = null) {
    let pdfWindow;

    try {
      pdfWindow = openCertificateActionWindow("Abriendo PDF original...");
    } catch (error) {
      setGeneratedCertificateActionMessage(error.message);
      return false;
    }

    try {
      setGeneratedCertificateAction({ id: certificate.id, type: "original" });
      setGeneratedCertificateActionMessage("");
      const request = await getRequestForGeneratedCertificate(certificate);
      const association = getCertificateAssociation(certificate, request ? [request] : printRequests);
      const pdfDocument = await resolveCertificatePdfDocument({
        certificate,
        request: association.request,
        student: association.student,
        loadStoredPdf: loadStoredCertificatePdfBlob,
        buildPdfBlob,
        acceptStoredUrl: true,
      });

      if (pdfDocument.source === "storage") {
        pdfWindow.location.replace(pdfDocument.storedSource.url);
      } else {
        openCertificatePdfBlob(
          pdfWindow,
          pdfDocument.blob,
          certificate.pdfFileName || `${certificate.folio || "certificado"}.pdf`
        );
      }
      setGeneratedCertificateActionMessage(
        pdfDocument.source === "storage"
          ? "PDF almacenado abierto en una pestaña nueva."
          : "PDF reconstruido desde la solicitud y abierto sin modificar registros."
      );
      return true;
    } catch (error) {
      console.error("No se pudo abrir el PDF original:", error);
      renderCertificateActionWindowError(pdfWindow, error?.message || "No se encontró el PDF original.");
      setGeneratedCertificateActionMessage(error?.message || "No se encontró el PDF original.");
      return false;
    } finally {
      setGeneratedCertificateAction(null);
    }
  }

  async function openRequestFromGeneratedCertificate(certificate) {
    try {
      setGeneratedCertificateAction({ id: certificate.id, type: "request" });
      setGeneratedCertificateActionMessage("");
      const request = await getRequestForGeneratedCertificate(certificate);

      if (!request) {
        throw new Error("No se encontró la solicitud asociada a este certificado.");
      }

      selectRequest(request);
      setActiveSection("certificates");
      setGeneratedCertificateActionMessage(`Solicitud ${request.folio || request.id} abierta.`);
      return true;
    } catch (error) {
      console.error("No se pudo abrir la solicitud del certificado:", error);
      setGeneratedCertificateActionMessage(error?.message || "No se pudo abrir la solicitud asociada.");
      return false;
    } finally {
      setGeneratedCertificateAction(null);
    }
  }

  function openCertificateRequest(request) {
    if (!request) return;

    selectRequest(request);
    setActiveSection("certificates");
  }

  async function reprintGeneratedCertificate(certificate, buildPdfBlob = null) {
    let printWindow;

    try {
      printWindow = openCertificateActionWindow("Cargando PDF original para imprimir...");
    } catch (error) {
      setGeneratedCertificateActionMessage(error.message);
      return false;
    }

    try {
      setGeneratedCertificateAction({ id: certificate.id, type: "reprint" });
      setGeneratedCertificateActionMessage("");
      const request = await getRequestForGeneratedCertificate(certificate);
      const association = getCertificateAssociation(certificate, request ? [request] : printRequests);
      const pdfDocument = await resolveCertificatePdfDocument({
        certificate,
        request: association.request,
        student: association.student,
        loadStoredPdf: loadStoredCertificatePdfBlob,
        buildPdfBlob,
      });

      renderCertificatePrintWindow(
        printWindow,
        pdfDocument.blob,
        certificate.pdfFileName || `${certificate.folio || "certificado"}.pdf`
      );
      setGeneratedCertificateActionMessage(
        pdfDocument.source === "storage"
          ? "PDF almacenado cargado; diálogo de impresión solicitado."
          : "PDF reconstruido desde la solicitud; diálogo de impresión solicitado."
      );
      return true;
    } catch (error) {
      console.error("No se pudo reimprimir el PDF original:", error);
      renderCertificateActionWindowError(printWindow, error?.message || "No se encontró el PDF original.");
      setGeneratedCertificateActionMessage(error?.message || "No se encontró el PDF original.");
      return false;
    } finally {
      setGeneratedCertificateAction(null);
    }
  }

  async function addSingleRequestStudent(event) {
    event.preventDefault();

    const cleanName = studentName.trim();

    if (!cleanName) {
      setRequestMessage("Escribe el nombre del alumno.");
      return;
    }

    const currentStudents = normalizeRequestStudents(selectedRequest?.students || []);
    const nextStudents = [
      ...currentStudents,
      {
        id: createStudentId(),
        name: cleanName,
        deliveryType: studentDeliveryType,
        status: "Pendiente",
      },
    ];

    await updateSelectedRequestStudents(nextStudents, "Alumno agregado correctamente.");
    setStudentName("");
  }

  async function addBulkRequestStudents(event) {
    event.preventDefault();

    const names = bulkStudentsText
      .split(/\r?\n/)
      .map((name) => name.trim())
      .filter(Boolean);

    if (names.length === 0) {
      setRequestMessage("Pega al menos un nombre de alumno.");
      return;
    }

    const currentStudents = normalizeRequestStudents(selectedRequest?.students || []);
    const nextStudents = [
      ...currentStudents,
      ...names.map((name) => ({
        id: createStudentId(),
        name,
        deliveryType: bulkStudentsDeliveryType,
        status: "Pendiente",
      })),
    ];

    await updateSelectedRequestStudents(nextStudents, `${names.length} alumnos agregados correctamente.`);
    setBulkStudentsText("");
  }

  async function updateRequestStudent(studentId, changes) {
    const currentStudents = normalizeRequestStudents(selectedRequest?.students || []);
    const nextStudents = currentStudents.map((student) => {
      if (student.id !== studentId) return student;

      return {
        ...student,
        ...changes,
        name: changes.name !== undefined ? String(changes.name || "").trim() : student.name,
      };
    });

    if (changes.name !== undefined && !String(changes.name || "").trim()) {
      setRequestMessage("El nombre del alumno no puede quedar vacío.");
      return;
    }

    await updateSelectedRequestStudents(nextStudents, "Alumno actualizado correctamente.");
  }

  async function deleteRequestStudent(studentId) {
    const currentStudents = normalizeRequestStudents(selectedRequest?.students || []);
    const nextStudents = currentStudents.filter((student) => student.id !== studentId);

    await updateSelectedRequestStudents(nextStudents, "Alumno eliminado correctamente.");
  }

  async function addStudentsAfterClosure(newPeopleDrafts) {
    const currentRequest = selectedRequest;

    if (!currentRequest || !selectedRequestId) {
      setRequestMessage("Selecciona primero una solicitud de certificado o diploma.");
      return { success: false };
    }

    if (!isRequestCertificateLike(currentRequest.requestType)) {
      setRequestMessage("Agregar personas solo aplica para certificados y diplomas.");
      return { success: false };
    }

    if (!canCurrentUserAddPeopleAfterClosure(currentRequest)) {
      setRequestMessage(
        "Solo un administrador o la persona de Imprenta asignada a esta solicitud puede agregar personas faltantes."
      );
      return { success: false };
    }

    if (savingStudents || addingStudentsAfterClosure) {
      return { success: false };
    }

    const cleanDrafts = (Array.isArray(newPeopleDrafts) ? newPeopleDrafts : [])
      .map((draft) => ({
        name: String(draft?.name || "").trim(),
        deliveryType: studentDeliveryTypes.includes(draft?.deliveryType) ? draft.deliveryType : "Impreso",
      }))
      .filter((draft) => draft.name);

    if (cleanDrafts.length === 0) {
      setRequestMessage("Captura al menos una persona con nombre válido.");
      return { success: false };
    }

    const auditUser = getAuditUser();
    const currentStudents = normalizeRequestStudents(currentRequest.students || []);
    const addedAtIso = new Date().toISOString();

    try {
      setAddingStudentsAfterClosure(true);
      setRequestMessage("");

      const newStudentsBase = cleanDrafts.map((draft) => ({
        id: createStudentId(),
        name: draft.name,
        deliveryType: draft.deliveryType,
        status: "Pendiente",
        addedAfterCreation: true,
        addedAfterCreationAt: addedAtIso,
        addedAfterCreationByUid: auditUser.uid,
        addedAfterCreationByName: auditUser.name,
        addedAfterCreationByEmail: auditUser.email,
      }));

      const combinedStudents = [...currentStudents, ...newStudentsBase];
      const newStudentsWithFolios = [];

      for (let offset = 0; offset < newStudentsBase.length; offset += 1) {
        const studentIndex = currentStudents.length + offset;
        // eslint-disable-next-line no-await-in-loop
        const studentWithFolio = await buildStudentWithFolio(
          currentRequest,
          combinedStudents[studentIndex],
          studentIndex,
          auditUser
        );
        newStudentsWithFolios.push(studentWithFolio);
      }

      const nextStudents = [...currentStudents, ...newStudentsWithFolios];
      const persisted = await updateSelectedRequestStudents(
        nextStudents,
        `${newStudentsWithFolios.length} persona(s) agregada(s) y folio(s) generado(s) correctamente.`
      );

      if (!persisted) {
        return { success: false };
      }

      const addedNames = newStudentsWithFolios.map((student) => student.name).join(", ");
      const newFolios = newStudentsWithFolios.map((student) => student.certificateFolio).join(", ");

      await createPrintshopLog({
        type: "STUDENTS_ADDED_AFTER_CLOSURE",
        module: "certificates",
        title: "Personas agregadas después del cierre",
        description: `${auditUser.name} agregó ${newStudentsWithFolios.length} persona(s) a la solicitud ${currentRequest.folio || currentRequest.id}: ${addedNames}. Folios nuevos: ${newFolios}.`,
        referenceType: "request",
        referenceId: currentRequest.id,
        requestId: currentRequest.id,
        requestFolio: currentRequest.folio || "",
        studentName: addedNames,
        productId: currentRequest.productId || "",
        productName: currentRequest.productName || "",
        campus: currentRequest.campus || "",
        level: currentRequest.level || "",
      });

      return { success: true, addedCount: newStudentsWithFolios.length };
    } catch (error) {
      console.error("No se pudieron agregar las personas después del cierre:", error);
      setRequestMessage("No se pudieron agregar las personas. Revisa la conexión o las reglas de Firestore.");
      return { success: false };
    } finally {
      setAddingStudentsAfterClosure(false);
    }
  }

  function validateStudentsReadyForFolios(request = selectedRequest) {
    if (!request || !selectedRequestId) {
      setRequestMessage("Selecciona primero una solicitud de certificado o diploma.");
      return false;
    }

    if (!isRequestCertificateLike(request.requestType)) {
      setRequestMessage("Los folios y QR solo aplican para certificados y diplomas.");
      return false;
    }

    if (!canCurrentUserManageRequestStudents(request)) {
      setRequestMessage("No tienes permisos para generar folios en esta solicitud.");
      return false;
    }

    const students = normalizeRequestStudents(request.students || []);

    if (students.length === 0) {
      setRequestMessage("Agrega primero la lista de alumnos.");
      return false;
    }

    const summary = getStudentValidationSummary(request);
    const listMatchesRequest =
      summary.totalMatches && summary.printedMatches && summary.digitalMatches;

    if (!listMatchesRequest) {
      setRequestMessage(
        "Antes de generar folios, revisa que el total de alumnos, impresos y digitales coincida con la solicitud."
      );
      return false;
    }

    return true;
  }

  async function buildStudentWithFolio(request, student, studentIndex, auditUser) {
    const certificateFolio = buildCertificateStudentFolio(request, studentIndex + 1);
    const validationCode = buildValidationCode(certificateFolio);
    const validationUrl = buildValidationUrl(validationCode);
    const qrDataUrl = await QRCode.toDataURL(validationUrl, {
      margin: 2,
      width: 180,
      errorCorrectionLevel: "M",
    });

    return {
      ...student,
      status: "Folio generado",
      certificateFolio,
      validationCode,
      validationUrl,
      qrDataUrl,
      qrGenerated: true,
      generatedAt: new Date().toISOString(),
      generatedByUid: auditUser.uid,
      generatedByName: auditUser.name,
      generatedByEmail: auditUser.email,
    };
  }

  async function generateStudentFolio(studentId) {
    const currentRequest = selectedRequest;

    if (!validateStudentsReadyForFolios(currentRequest)) return;

    const currentStudents = normalizeRequestStudents(currentRequest.students || []);
    const studentIndex = currentStudents.findIndex((student) => student.id === studentId);

    if (studentIndex < 0) {
      setRequestMessage("No se encontró el alumno seleccionado.");
      return;
    }

    if (currentStudents[studentIndex].certificateFolio) {
      setRequestMessage("Este alumno ya tiene folio y QR de validación.");
      return;
    }

    const auditUser = getAuditUser();

    try {
      setGeneratingStudentId(studentId);
      setRequestMessage("");

      const studentWithFolio = await buildStudentWithFolio(
        currentRequest,
        currentStudents[studentIndex],
        studentIndex,
        auditUser
      );

      const nextStudents = currentStudents.map((student) =>
        student.id === studentId ? studentWithFolio : student
      );

      await updateSelectedRequestStudents(nextStudents, "Folio y QR generados correctamente.");
    } catch (error) {
      console.error("No se pudo generar el folio/QR del alumno:", error);
      setRequestMessage("No se pudo generar el folio y QR. Revisa que la librería qrcode esté instalada correctamente.");
    } finally {
      setGeneratingStudentId(null);
    }
  }

  async function generateAllStudentFolios() {
    const currentRequest = selectedRequest;

    if (!validateStudentsReadyForFolios(currentRequest)) return;

    const currentStudents = normalizeRequestStudents(currentRequest.students || []);
    const pendingStudents = currentStudents.filter((student) => !student.certificateFolio);

    if (pendingStudents.length === 0) {
      setRequestMessage("Todos los alumnos ya tienen folio y QR de validación.");
      return;
    }

    const auditUser = getAuditUser();

    try {
      setGeneratingStudentId("all");
      setRequestMessage("");

      const nextStudents = [];

      for (let index = 0; index < currentStudents.length; index += 1) {
        const student = currentStudents[index];

        if (student.certificateFolio) {
          nextStudents.push(student);
        } else {
          // eslint-disable-next-line no-await-in-loop
          const studentWithFolio = await buildStudentWithFolio(
            currentRequest,
            student,
            index,
            auditUser
          );
          nextStudents.push(studentWithFolio);
        }
      }

      await updateSelectedRequestStudents(
        nextStudents,
        `${pendingStudents.length} folios y QR generados correctamente.`
      );
    } catch (error) {
      console.error("No se pudieron generar los folios/QR:", error);
      setRequestMessage("No se pudieron generar los folios y QR. Revisa que la librería qrcode esté instalada correctamente.");
    } finally {
      setGeneratingStudentId(null);
    }
  }

  async function resetRequestCertificateFolios(request = selectedRequest) {
    const currentRequest = request || selectedRequest;

    if (!currentRequest?.id || !selectedRequestId) {
      setRequestMessage("Selecciona primero una solicitud de certificado o diploma.");
      return;
    }

    if (!isRequestCertificateLike(currentRequest.requestType)) {
      setRequestMessage("El reinicio de folios solo aplica para certificados y diplomas.");
      return;
    }

    if (!canCurrentUserManageRequestStudents(currentRequest)) {
      setRequestMessage("No tienes permisos para reiniciar folios en esta solicitud.");
      return;
    }

    const currentStudents = normalizeRequestStudents(currentRequest.students || []);
    const studentsWithGeneratedData = currentStudents.filter(hasStudentGeneratedCertificateData);
    const certificatesToCancel = generatedCertificates.filter(
      (certificate) =>
        certificate.requestId === currentRequest.id &&
        certificate.status !== "Cancelado" &&
        (
          currentStudents.some((student) =>
            certificate.studentId === student.id ||
            certificate.validationCode === student.validationCode ||
            certificate.folio === student.certificateFolio ||
            certificate.id === student.certificateRecordId
          ) ||
          certificate.requestId === currentRequest.id
        )
    );

    if (studentsWithGeneratedData.length === 0 && certificatesToCancel.length === 0) {
      setRequestMessage("Esta solicitud no tiene folios generados para reiniciar.");
      return;
    }

    const confirmed = window.confirm(
      "Esto eliminara los folios generados, pero conservara los alumnos. Podras corregir datos y generar nuevos folios."
    );

    if (!confirmed) return;

    const auditUser = getAuditUser();
    const resetAtIso = new Date().toISOString();
    const resetStudents = currentStudents.map(resetStudentGeneratedCertificateData);
    const requestRef = doc(db, "printRequests", currentRequest.id);
    const batch = writeBatch(db);

    batch.update(requestRef, {
      students: resetStudents,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    });

    studentsWithGeneratedData
      .filter((student) => student.certificateFolio && student.validationCode)
      .forEach((student) => {
        batch.set(
          doc(db, "publicCertificateValidations", getRequestStudentValidationId(currentRequest, student)),
          buildPublicCertificateValidationPayload(
            {
              folio: student.certificateFolio,
              validationCode: student.validationCode,
              validationUrl: student.validationUrl || buildValidationUrl(student.validationCode),
              studentName: student.name,
              campus: currentRequest.campus || "Sin plantel",
              requestId: currentRequest.id,
              requestFolio: currentRequest.folio || "",
              requestType: currentRequest.requestType || "Certificado",
              productName: currentRequest.productName || "",
              level: currentRequest.level || "No aplica",
              programName:
                currentRequest.certificateTemplateProgramName ||
                getCertificateTrackLabel(currentRequest),
              templateName:
                currentRequest.certificateTemplateName ||
                "Plantilla no especificada",
              issueDate: getCertificateIssueDate(currentRequest),
              teacherName:
                currentRequest.teacherSignerName ||
                currentRequest.teacherName ||
                "",
              status: "Cancelado",
            },
            {
              generationMode: "request",
              updatedAt: serverTimestamp(),
            }
          ),
          { merge: true }
        );
      });

    certificatesToCancel.forEach((certificate) => {
      const certificatePayload = {
        status: "Cancelado",
        cancelledAt: serverTimestamp(),
        cancelledByUid: auditUser.uid,
        cancelledByName: auditUser.name,
        cancelledByEmail: auditUser.email,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      };

      batch.update(doc(db, "generatedCertificates", certificate.id), certificatePayload);

      const publicCertificateId = sanitizeGeneratedCertificateId(
        certificate.validationCode || certificate.id || certificate.folio
      );

      batch.set(
        doc(db, "publicCertificateValidations", publicCertificateId),
        buildPublicCertificateValidationPayload(certificate, {
          status: "Cancelado",
          updatedAt: serverTimestamp(),
        }),
        { merge: true }
      );
    });
    batch.set(doc(db, "certificateHistoryBatches", currentRequest.id), {
      requestId: currentRequest.id,
      loteId: currentRequest.id,
      requestFolio: currentRequest.folio || "",
      status: "Cancelado",
      certificateCount: certificatesToCancel.length,
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    }, { merge: true });

    try {
      setSavingStudents(true);
      setRequestMessage("");
      await batch.commit();

      setGeneratedCertificates((current) =>
        current.map((certificate) =>
          certificatesToCancel.some((item) => item.id === certificate.id)
            ? {
                ...certificate,
                status: "Cancelado",
                cancelledAt: resetAtIso,
                cancelledByUid: auditUser.uid,
                cancelledByName: auditUser.name,
                cancelledByEmail: auditUser.email,
                updatedAt: resetAtIso,
                updatedByUid: auditUser.uid,
                updatedByName: auditUser.name,
                updatedByEmail: auditUser.email,
              }
            : certificate
        )
      );

      await createPrintshopLog({
        type: "CERTIFICATE_FOLIOS_RESET",
        module: "certificates",
        title: "Folios de certificados reiniciados",
        description: `Se reiniciaron ${studentsWithGeneratedData.length} folio(s) de la solicitud ${currentRequest.folio || currentRequest.id}. Los alumnos se conservaron.`,
        referenceType: "request",
        referenceId: currentRequest.id,
        requestId: currentRequest.id,
        requestFolio: currentRequest.folio || "",
        productId: currentRequest.productId || "",
        productName: currentRequest.productName || "",
        campus: currentRequest.campus || "",
        level: currentRequest.level || "",
      });

      setRequestMessage(
        `Se reiniciaron ${studentsWithGeneratedData.length} folio(s). Los alumnos siguen disponibles para correccion.`
      );
    } catch (error) {
      console.error("No se pudieron reiniciar los folios:", error);
      setRequestMessage(
        error?.code === "permission-denied"
          ? "No tienes permisos para reiniciar estos folios. Revisa asignacion de la solicitud."
          : "No se pudieron reiniciar los folios. Revisa reglas de Firestore."
      );
    } finally {
      setSavingStudents(false);
    }
  }

  function handleProductInputChange(event) {
    const { name, value, type, checked } = event.target;

    setProductForm((current) => ({
      ...current,
      [name]: type === "checkbox" ? checked : value,
    }));
  }

  function handleNumberInputChange(event) {
    const { name, value } = event.target;
    const nextValue = Number(value);

    setProductForm((current) => ({
      ...current,
      [name]: Number.isNaN(nextValue) ? 0 : Math.max(0, nextValue),
    }));
  }

  function addProductRecipeItem() {
    setFormMessage("");

    if (!productForm.recipeSupplyId) {
      setFormMessage("Selecciona un insumo para agregarlo a la receta.");
      return;
    }

    const quantityPerUnit = Number(productForm.recipeQuantityPerUnit || 0);

    if (quantityPerUnit <= 0) {
      setFormMessage("La cantidad por unidad producida debe ser mayor que cero.");
      return;
    }

    const selectedSupply = supplyItems.find((item) => item.id === productForm.recipeSupplyId);

    if (!selectedSupply) {
      setFormMessage("No se encontró el insumo seleccionado.");
      return;
    }

    setProductForm((current) => {
      const currentRecipe = normalizeProductRecipe(current.productionRecipe).filter(
        (item) => item.supplyId !== selectedSupply.id
      );

      return {
        ...current,
        productionRecipe: [
          ...currentRecipe,
          {
            id: buildRecipeItemId(),
            supplyId: selectedSupply.id,
            supplyName: selectedSupply.name || "Insumo",
            category: selectedSupply.category || "",
            quantityPerUnit,
            unit: current.recipeUnit || selectedSupply.contentUnit || selectedSupply.stockUnit || "Pieza",
            notes: current.recipeNotes || "",
            active: true,
          },
        ],
        recipeSupplyId: "",
        recipeQuantityPerUnit: 0,
        recipeUnit: "Hoja",
        recipeNotes: "",
      };
    });
  }

  function removeProductRecipeItem(recipeItemId) {
    setProductForm((current) => ({
      ...current,
      productionRecipe: normalizeProductRecipe(current.productionRecipe).filter(
        (item) => item.id !== recipeItemId
      ),
    }));
  }

  function resetProductForm() {
    setSelectedProductId(null);
    setProductForm(productFormInitialState);
    setFormMessage("");
  }

  function selectProduct(product) {
    setSelectedProductId(product.id);
    setFormMessage("");
    setProductForm({
      name: product.name || "",
      category: product.category || "Libro",
      productionType: product.productionType || "Producto terminado",
      level: product.level || "No aplica",
      unit: product.unit || "Pieza",
      minStock: Number(product.minStock || 0),
      idealStock: Number(product.idealStock || 0),
      requiresPrinting: product.requiresPrinting !== false,
      requiresBinding: product.requiresBinding === true,
      requiresCutting: product.requiresCutting === true,
      requiresQualityCheck: product.requiresQualityCheck !== false,
      requiresSignature: product.requiresSignature === true,
      requiresValidationQr: product.requiresValidationQr === true,
      productionRecipe: normalizeProductRecipe(product.productionRecipe),
      recipeSupplyId: "",
      recipeQuantityPerUnit: 0,
      recipeUnit: "Hoja",
      recipeNotes: "",
      active: product.active !== false,
      notes: product.notes || "",
    });
  }

  async function saveProduct(event) {
    event.preventDefault();
    setFormMessage("");

    const trimmedName = productForm.name.trim();

    if (!trimmedName) {
      setFormMessage("Escribe el nombre del producto antes de guardar.");
      return;
    }

    if (Number(productForm.idealStock) < Number(productForm.minStock)) {
      setFormMessage("El stock ideal no puede ser menor que el stock mínimo.");
      return;
    }

    const auditUser = getAuditUser();
    const {
      recipeSupplyId,
      recipeQuantityPerUnit,
      recipeUnit,
      recipeNotes,
      ...productPayloadFields
    } = productForm;
    const payload = {
      ...productPayloadFields,
      name: trimmedName,
      minStock: Number(productForm.minStock || 0),
      idealStock: Number(productForm.idealStock || 0),
      productionRecipe: normalizeProductRecipe(productForm.productionRecipe),
      updatedAt: serverTimestamp(),
      updatedByUid: auditUser.uid,
      updatedByName: auditUser.name,
      updatedByEmail: auditUser.email,
    };

    try {
      setSavingProduct(true);

      if (selectedProductId) {
        await updateDoc(doc(db, "printProducts", selectedProductId), payload);
        setFormMessage("Producto actualizado correctamente.");
      } else {
        await addDoc(collection(db, "printProducts"), {
          ...payload,
          createdAt: serverTimestamp(),
          createdByUid: auditUser.uid,
          createdByName: auditUser.name,
          createdByEmail: auditUser.email,
        });
        setProductForm(productFormInitialState);
        setFormMessage("Producto agregado correctamente.");
      }
    } catch (error) {
      console.error("No se pudo guardar el producto de imprenta:", error);
      setFormMessage(
        "No se pudo guardar. Revisa que hayas publicado las reglas nuevas de Firestore."
      );
    } finally {
      setSavingProduct(false);
    }
  }

  async function toggleProductStatus(product) {
    if (!product?.id) return;

    const auditUser = getAuditUser();

    try {
      await updateDoc(doc(db, "printProducts", product.id), {
        active: product.active === false,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });
    } catch (error) {
      console.error("No se pudo cambiar el estado del producto:", error);
      setProductsError(
        "No se pudo cambiar el estado del producto. Revisa permisos de Firestore."
      );
    }
  }

  async function seedBaseProducts() {
    if (!isAdmin || products.length > 0) return;

    const auditUser = getAuditUser();
    const batch = writeBatch(db);

    basePrintProducts.forEach((product) => {
      const productRef = doc(collection(db, "printProducts"));
      batch.set(productRef, {
        ...product,
        createdAt: serverTimestamp(),
        createdByUid: auditUser.uid,
        createdByName: auditUser.name,
        createdByEmail: auditUser.email,
        updatedAt: serverTimestamp(),
        updatedByUid: auditUser.uid,
        updatedByName: auditUser.name,
        updatedByEmail: auditUser.email,
      });
    });

    try {
      setSeedingProducts(true);
      await batch.commit();
      setFormMessage("Productos base cargados correctamente.");
    } catch (error) {
      console.error("No se pudieron cargar los productos base:", error);
      setFormMessage(
        "No se pudieron cargar los productos base. Publica primero las reglas nuevas de Firestore."
      );
    } finally {
      setSeedingProducts(false);
    }
  }

  function handleInventoryInputChange(event) {
    const { name, value } = event.target;

    setInventoryMessage("");

    setInventoryForm((current) => {
      const nextForm = {
        ...current,
        [name]: value,
      };

      if (name === "productId") {
        const selectedProduct = products.find((product) => product.id === value);

        if (selectedProduct) {
          nextForm.minStock = Number(selectedProduct.minStock || 0);
          nextForm.idealStock = Number(selectedProduct.idealStock || 0);
        }
      }

      return nextForm;
    });
  }

  function handleInventoryNumberInputChange(event) {
    const { name, value } = event.target;
    const nextValue = Number(value);

    setInventoryMessage("");

    setInventoryForm((current) => ({
      ...current,
      [name]: Number.isNaN(nextValue) ? 0 : Math.max(0, nextValue),
    }));
  }

