function EditorTemplateLayer({
  elementKey,
  selectedElement,
  position,
  className = "",
  onSelectElement,
  onPointerDown,
  children,
  isQr = false,
  isImage = false,
}) {
  const normalized = normalizeTemplatePosition(position, {});
  if (normalized.active === false) return null;

  const style = isQr
    ? getTemplateElementStyle(normalized, { size: true })
    : isImage
      ? getTemplateSignatureBoxStyle(normalized)
      : getTemplateTextStyle(normalized);

  return (
    <button
      type="button"
      className={`editor-template-layer ${className} ${selectedElement === elementKey ? "selected" : ""}`}
      style={style}
      onClick={() => onSelectElement(elementKey)}
      onPointerDown={(event) => onPointerDown?.(event, elementKey)}
    >
      {children}
    </button>
  );
}

function EditorCustomImageLayer({
  customImage,
  selectedElement,
  onSelectElement,
  onPointerDown,
}) {
  const normalized = normalizeTemplateCustomImage(customImage);
  if (normalized.active === false || !normalized.imageDataUrl && !normalized.imageUrl) return null;

  const elementKey = getTemplateCustomImageKey(normalized.id);

  return (
    <button
      type="button"
      className={`editor-template-layer editor-layer-custom-image ${selectedElement === elementKey ? "selected" : ""}`}
      style={getTemplateCustomImageStyle(normalized)}
      onClick={() => onSelectElement(elementKey)}
      onPointerDown={(event) => onPointerDown?.(event, elementKey)}
    >
      <img src={normalized.imageDataUrl || normalized.imageUrl} alt={normalized.label} draggable="false" />
    </button>
  );
}

function EditorCustomTextLayer({
  customText,
  programLabel,
  selectedElement,
  onSelectElement,
  onPointerDown,
}) {
  const normalized = normalizeTemplateCustomText(customText);
  if (normalized.active === false) return null;

  const elementKey = getTemplateCustomTextKey(normalized.id);

  return (
    <button
      type="button"
      className={`editor-template-layer editor-layer-text custom ${selectedElement === elementKey ? "selected" : ""}`}
      style={getTemplateCustomTextStyle(normalized)}
      onClick={() => onSelectElement(elementKey)}
      onPointerDown={(event) => onPointerDown?.(event, elementKey)}
    >
      <CertificateBodySegments segments={getResolvedCustomTextSegments(normalized, programLabel)} />
    </button>
  );
}

function CertificateSignersView({
  signers,
  loadingSigners,
  signersError,
  signerForm,
  selectedSigner,
  selectedSignerId,
  signatureFile,
  savingSigner,
  signerMessage,
  isAdmin,
  onSignerInputChange,
  onSignatureFileChange,
  onSaveSigner,
  onSelectSigner,
  onResetSignerForm,
  onToggleSignerStatus,
  onSoftDeleteSigner,
}) {
  const principalCount = signers.filter((signer) => signer.type === "Principal" && signer.active !== false).length;
  const teacherCount = signers.filter((signer) => signer.type === "Teacher" && signer.active !== false).length;
  const [signerFocusOpen, setSignerFocusOpen] = useState(false);
  const [recentlySavedSignerId, setRecentlySavedSignerId] = useState("");

  function openSignerFocus(signer = null) {
    if (signer) {
      onSelectSigner(signer);
    } else {
      onResetSignerForm();
    }
    setSignerFocusOpen(true);
  }

  function closeSignerFocus() {
    onResetSignerForm();
    setSignerFocusOpen(false);
  }

  async function handleSaveSignerSubmit(event) {
    const result = await onSaveSigner(event);

    if (result?.success) {
      setSignerFocusOpen(false);

      if (result.signerId) {
        setRecentlySavedSignerId(result.signerId);
        setTimeout(() => setRecentlySavedSignerId(""), 3000);
      }
    }
  }


  return (
    <section className="printshop-signers-section printshop-tab-redesign signers-redesign-page">
      <div className="printshop-section-heading">
        <div>
          <p className="section-kicker printshop-kicker">Certificados</p>
          <h2>Catálogo de firmas</h2>
          <p>
            Administra directores, principales y teachers con su firma digital para que los certificados se generen con datos reales.
          </p>
        </div>

        {isAdmin && (
          <button type="button" className="visual-primary-button" onClick={() => openSignerFocus()}>
            + Nuevo firmante
          </button>
        )}
      </div>

      <div className="catalog-metrics-grid signers-metrics-grid">
        <CatalogMetric tone="blue" icon="✒" label="Firmantes" value={signers.length} />
        <CatalogMetric tone="green" icon="●" label="Principales activos" value={principalCount} />
        <CatalogMetric tone="teal" icon="◎" label="Teachers activos" value={teacherCount} />
      </div>

      <div className={`printshop-signers-layout ${signerFocusOpen ? "printshop-focused-layout" : ""}`}>
        <Panel title="Firmantes registrados" icon="✒" actionLabel={`${signers.length} registros`}>
          {loadingSigners ? (
            <div className="empty-state small"><div><PrintshopIcon name="target" /></div><p>Cargando firmas...</p></div>
          ) : signersError ? (
            <div className="message-box error">{signersError}</div>
          ) : signers.length === 0 ? (
            <div className="empty-state small"><div><PrintshopIcon name="signers" /></div><p>No hay firmantes registrados todavía.</p></div>
          ) : (
            <div className="signers-grid">
              {signers.map((signer) => (
                <article
                  key={signer.id}
                  className={`signer-card ${signer.active === false ? "inactive" : ""} ${signer.id === recentlySavedSignerId ? "signer-card-recently-saved" : ""}`}
                >
                  <div className="signer-card-header">
                    <div>
                      <strong>{signer.name}</strong>
                      <p>{signer.role} - {signer.campus || "Sin plantel"}</p>
                    </div>
                    <StatusBadge tone={signer.type === "Principal" ? "blue" : "teal"}>{signer.type}</StatusBadge>
                  </div>

                  <div className="signer-signature-preview">
                    {signer.signatureUrl ? (
                      <img src={signer.signatureUrl} alt={`Firma de ${signer.name}`} />
                    ) : (
                      <span>Sin firma</span>
                    )}
                  </div>

                  <div className="signer-card-footer">
                    <StatusBadge tone={signer.active === false ? "red" : "green"}>
                      {signer.active === false ? "Inactivo" : "Activo"}
                    </StatusBadge>
                    <div className="table-actions">
                      <button type="button" onClick={() => openSignerFocus(signer)}>Editar</button>
                      {isAdmin && (
                        <>
                          <button type="button" onClick={() => onToggleSignerStatus(signer)}>
                            {signer.active === false ? "Activar" : "Desactivar"}
                          </button>
                          <button
                            type="button"
                            className="danger-table-button"
                            onClick={() => onSoftDeleteSigner(signer)}
                          >
                            Eliminar
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </Panel>

        {signerFocusOpen && (
          <div className="printshop-focused-header">
            <button type="button" className="visual-outline-button" onClick={closeSignerFocus}>
              ← Regresar a firmas
            </button>
            <span>{selectedSigner ? "Vista enfocada de edición" : "Vista enfocada de alta"}</span>
          </div>
        )}

        <Panel
          title={selectedSigner ? "Editar firmante" : "Nuevo firmante"}
          icon={selectedSigner ? "✎" : "＋"}
          actionLabel={selectedSigner ? "Edición" : "Alta"}
        >
          <form className="printshop-product-form signer-form" onSubmit={handleSaveSignerSubmit}>
            <label>
              <span>Tipo de firmante</span>
              <select name="type" value={signerForm.type} onChange={onSignerInputChange} disabled={!isAdmin}>
                {certificateSignerTypes.map((type) => <option key={type}>{type}</option>)}
              </select>
            </label>

            <label>
              <span>Plantel</span>
              <select name="campus" value={signerForm.campus} onChange={onSignerInputChange} disabled={!isAdmin}>
                {CERTIFICATE_SIGNER_CAMPUS_OPTIONS.map((campus) => <option key={campus}>{campus}</option>)}
              </select>
            </label>

            {signerForm.campus === "Otro" && (
              <label>
                <span>Nombre del plantel</span>
                <input
                  name="customCampus"
                  value={signerForm.customCampus}
                  onChange={onSignerInputChange}
                  placeholder="Escribe el nombre del plantel"
                  maxLength={120}
                  required
                  disabled={!isAdmin}
                />
              </label>
            )}

            <label className="full">
              <span>Nombre</span>
              <input name="name" value={signerForm.name} onChange={onSignerInputChange} placeholder="Nombre que aparecerá en el certificado" disabled={!isAdmin} />
            </label>

            <label className="full">
              <span>Cargo / texto debajo del nombre</span>
              <input name="role" value={signerForm.role} onChange={onSignerInputChange} placeholder="Principal, Director, Teacher..." disabled={!isAdmin} />
            </label>

            <label className="full">
              <span>Imagen de firma</span>
              <input
                type="file"
                accept="image/png,image/jpeg,image/webp"
                onChange={(event) => onSignatureFileChange(event.target.files?.[0] || null)}
                disabled={!isAdmin || savingSigner}
              />
              <small>Usa PNG transparente si es posible. Máximo 5 MB.</small>
            </label>

            {(signatureFile || signerForm.signatureUrl) && (
              <div className="signer-form-preview full">
                <span>Vista previa de firma</span>
                {signatureFile ? (
                  <strong>{signatureFile.name}</strong>
                ) : (
                  <img src={signerForm.signatureUrl} alt="Firma actual" />
                )}
              </div>
            )}

            <label className="full">
              <span>Notas</span>
              <textarea name="notes" value={signerForm.notes} onChange={onSignerInputChange} placeholder="Observaciones internas" disabled={!isAdmin} />
            </label>

            <label className="product-check active-check full">
              <input type="checkbox" name="active" checked={signerForm.active} onChange={onSignerInputChange} disabled={!isAdmin} />
              <span>Firmante activo</span>
            </label>

            {signerMessage && <div className="message-box full">{signerMessage}</div>}

            <div className="printshop-form-actions full">
              {selectedSignerId && (
                <button type="button" className="visual-outline-button" onClick={onResetSignerForm} disabled={savingSigner}>
                  Nuevo firmante
                </button>
              )}
              <button type="submit" className="visual-primary-button" disabled={!isAdmin || savingSigner}>
                {savingSigner ? "Guardando..." : selectedSignerId ? "Guardar cambios" : "Crear firmante"}
              </button>
            </div>
          </form>
        </Panel>
      </div>
    </section>
  );
}

function ProductCatalogView({
  products,
  filteredProducts,
  loadingProducts,
  productsError,
  productStats,
  productForm,
  formMessage,
  savingProduct,
  seedingProducts,
  selectedProduct,
  selectedProductId,
  productSearch,
  categoryFilter,
  typeFilter,
  statusFilter,
  isAdmin,
  canManageCatalog = isAdmin,
  supplyItems,
  onSearchChange,
  onCategoryFilterChange,
  onTypeFilterChange,
  onStatusFilterChange,
  onInputChange,
  onNumberInputChange,
  onAddRecipeItem,
  onRemoveRecipeItem,
  onSaveProduct,
  onSelectProduct,
  onResetForm,
  onToggleStatus,
  onSeedBaseProducts,
  onSoftDeleteProduct,
}) {
  const [productFocusOpen, setProductFocusOpen] = useState(false);

  function openProductFocus(product = null) {
    if (product) {
      onSelectProduct(product);
    } else {
      onResetForm();
    }
    setProductFocusOpen(true);
  }

  function closeProductFocus() {
    onResetForm();
    setProductFocusOpen(false);
  }

  return (
    <section className="printshop-catalog-page printshop-tab-redesign product-catalog-redesign">
      <div className="printshop-catalog-hero">
        <div>
          <p className="section-kicker printshop-kicker">Catálogo</p>
          <h2>Catálogo de productos</h2>
          <p>
            Registra libros, certificados, diplomas, volantes, viniles y
            materiales internos. Este catálogo será la base de lotes,
            solicitudes, inventario terminado y certificados automáticos.
          </p>
        </div>

        {products.length === 0 && isAdmin && (
          <button
            type="button"
            className="visual-primary-button"
            onClick={onSeedBaseProducts}
            disabled={seedingProducts}
          >
            {seedingProducts ? "Cargando..." : "Cargar productos base"}
          </button>
        )}
      </div>

      <div className="printshop-catalog-metrics">
        <CatalogMetric tone="blue" icon="▤" label="Total" value={productStats.total} />
        <CatalogMetric tone="green" icon="✓" label="Activos" value={productStats.active} />
        <CatalogMetric tone="orange" icon="▣" label="Libros" value={productStats.books} />
        <CatalogMetric
          tone="purple"
          icon="◎"
          label="Docs. generados"
          value={productStats.generatedDocuments}
        />
        <CatalogMetric tone="red" icon="○" label="Inactivos" value={productStats.inactive} />
      </div>

      {productsError && <div className="form-error">{productsError}</div>}

      <div className={`printshop-catalog-layout ${productFocusOpen ? "printshop-focused-layout" : ""}`}>
        <div className="printshop-catalog-main">
          <Panel title="Productos registrados" icon="▤" actionLabel={`${filteredProducts.length} visibles`}>
            <div className="printshop-catalog-toolbar">
              <label className="printshop-catalog-search">
                <span>Buscar</span>
                <input
                  type="search"
                  placeholder="Nombre, categoría o nivel"
                  value={productSearch}
                  onChange={(event) => onSearchChange(event.target.value)}
                />
              </label>

              <label>
                <span>Categoría</span>
                <select
                  value={categoryFilter}
                  onChange={(event) => onCategoryFilterChange(event.target.value)}
                >
                  <option>Todas</option>
                  {productCategories.map((category) => (
                    <option key={category}>{category}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Tipo</span>
                <select
                  value={typeFilter}
                  onChange={(event) => onTypeFilterChange(event.target.value)}
                >
                  <option>Todos</option>
                  {productionTypes.map((type) => (
                    <option key={type}>{type}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Estado</span>
                <select
                  value={statusFilter}
                  onChange={(event) => onStatusFilterChange(event.target.value)}
                >
                  <option>Activos</option>
                  <option>Inactivos</option>
                  <option>Todos</option>
                </select>
              </label>

              {canManageCatalog && (
                <button
                  type="button"
                  className="visual-primary-button printshop-toolbar-action"
                  onClick={() => openProductFocus()}
                >
                  + Nuevo producto
                </button>
              )}
            </div>

            {loadingProducts ? (
              <div className="printshop-empty-catalog">
                <div><PrintshopIcon name="requests" /></div>
                <h3>Cargando catálogo...</h3>
                <p>Estamos consultando los productos registrados en Firestore.</p>
              </div>
            ) : filteredProducts.length === 0 ? (
              <div className="printshop-empty-catalog">
                <div><PrintshopIcon name="requests" /></div>
                <h3>No hay productos para mostrar</h3>
                <p>
                  Ajusta los filtros o registra el primer producto del catálogo
                  de imprenta.
                </p>
              </div>
            ) : (
              <div className="printshop-table-wrap">
                <table className="printshop-table printshop-products-table">
                  <thead>
                    <tr>
                      <th>Producto</th>
                      <th>Categoría</th>
                      <th>Tipo</th>
                      <th>Nivel</th>
                      <th>Stock</th>
                      <th>Requisitos</th>
                      <th>Estado</th>
                      <th>Acciones</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredProducts.map((product) => (
                      <tr
                        key={product.id}
                        className={selectedProductId === product.id ? "selected-product-row" : ""}
                      >
                        <td>
                          <strong>{product.name}</strong>
                          <span>{product.unit || "Pieza"}</span>
                        </td>
                        <td>{product.category}</td>
                        <td>{product.productionType}</td>
                        <td>{product.level || "No aplica"}</td>
                        <td>
                          <span>Mín. {Number(product.minStock || 0)}</span>
                          <span>Ideal {Number(product.idealStock || 0)}</span>
                        </td>
                        <td>
                          <RequirementChips product={product} />
                          {normalizeProductRecipe(product.productionRecipe).length > 0 && (
                            <small className="product-recipe-count">
                              Receta: {normalizeProductRecipe(product.productionRecipe).length} insumo(s)
                            </small>
                          )}
                        </td>
                        <td>
                          <StatusBadge tone={product.active === false ? "red" : "green"}>
                            {product.active === false ? "Inactivo" : "Activo"}
                          </StatusBadge>
                        </td>
                        <td>
                          <div className="printshop-product-actions">
                            <button type="button" onClick={() => openProductFocus(product)}>
                              Editar
                            </button>
                            <button type="button" onClick={() => onToggleStatus(product)}>
                              {product.active === false ? "Activar" : "Desactivar"}
                            </button>
                            {isAdmin && (
                              <button
                                type="button"
                                className="danger-table-button"
                                onClick={() => onSoftDeleteProduct(product)}
                              >
                                Eliminar
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Panel>
        </div>

        <aside className="printshop-catalog-side">
          <Panel
            title={selectedProduct ? "Editar producto" : "Nuevo producto"}
            icon={selectedProduct ? "✎" : "＋"}
            actionLabel={selectedProduct ? "Editando" : "Alta"}
          >
            {productFocusOpen && (
              <div className="printshop-focused-header">
                <button type="button" className="visual-outline-button" onClick={closeProductFocus}>
                  ← Regresar al catálogo
                </button>
                <span>{selectedProduct ? "Vista enfocada de edición" : "Vista enfocada de alta"}</span>
              </div>
            )}

            <form className="printshop-product-form" onSubmit={onSaveProduct}>
              <label className="full">
                <span>Nombre del producto</span>
                <input
                  name="name"
                  value={productForm.name}
                  onChange={onInputChange}
                  placeholder="Ej. Journey A1"
                />
              </label>

              <label>
                <span>Categoría</span>
                <select
                  name="category"
                  value={productForm.category}
                  onChange={onInputChange}
                >
                  {productCategories.map((category) => (
                    <option key={category}>{category}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Tipo de producción</span>
                <select
                  name="productionType"
                  value={productForm.productionType}
                  onChange={onInputChange}
                >
                  {productionTypes.map((type) => (
                    <option key={type}>{type}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Nivel</span>
                <select name="level" value={productForm.level} onChange={onInputChange}>
                  {levels.map((level) => (
                    <option key={level}>{level}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Unidad</span>
                <select name="unit" value={productForm.unit} onChange={onInputChange}>
                  {units.map((unit) => (
                    <option key={unit}>{unit}</option>
                  ))}
                </select>
              </label>

              <label>
                <span>Stock mínimo</span>
                <input
                  type="number"
                  name="minStock"
                  min="0"
                  value={productForm.minStock}
                  onChange={onNumberInputChange}
                />
              </label>

              <label>
                <span>Stock ideal</span>
                <input
                  type="number"
                  name="idealStock"
                  min="0"
                  value={productForm.idealStock}
                  onChange={onNumberInputChange}
                />
              </label>

              <div className="printshop-product-checks full">
                <span>Requisitos del producto</span>
                <ProductCheckbox
                  name="requiresPrinting"
                  label="Requiere impresión"
                  checked={productForm.requiresPrinting}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="requiresBinding"
                  label="Requiere encuadernado"
                  checked={productForm.requiresBinding}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="requiresCutting"
                  label="Requiere corte"
                  checked={productForm.requiresCutting}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="requiresQualityCheck"
                  label="Requiere revisión de calidad"
                  checked={productForm.requiresQualityCheck}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="requiresSignature"
                  label="Requiere firma"
                  checked={productForm.requiresSignature}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="requiresValidationQr"
                  label="Requiere folio / QR de validación"
                  checked={productForm.requiresValidationQr}
                  onChange={onInputChange}
                />
                <ProductCheckbox
                  name="active"
                  label="Producto activo"
                  checked={productForm.active}
                  onChange={onInputChange}
                />
              </div>

              <div className="product-recipe-box full">
                <div className="product-recipe-header">
                  <div>
                    <strong>Receta de producción</strong>
                    <p>
                      Define cuánto insumo se usa por cada unidad producida. Para laminado, usa metros;
                      por ejemplo, 0.35 metros por libro. Para papel, usa hojas por libro.
                    </p>
                  </div>
                  <StatusBadge tone={normalizeProductRecipe(productForm.productionRecipe).length > 0 ? "green" : "orange"}>
                    {normalizeProductRecipe(productForm.productionRecipe).length} insumo(s)
                  </StatusBadge>
                </div>

                <div className="product-recipe-inputs">
                  <label>
                    <span>Insumo</span>
                    <select
                      name="recipeSupplyId"
                      value={productForm.recipeSupplyId}
                      onChange={onInputChange}
                    >
                      <option value="">Seleccionar insumo</option>
                      {supplyItems.filter(isVisibleSupplyItem).map((item) => (
                        <option key={item.id} value={item.id}>
                          {item.name} - {item.stockUnit}
                        </option>
                      ))}
                    </select>
                  </label>

                  <label>
                    <span>Cantidad por {productForm.unit || "unidad"}</span>
                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      name="recipeQuantityPerUnit"
                      value={productForm.recipeQuantityPerUnit}
                      onChange={onNumberInputChange}
                      placeholder="Ej. 40"
                    />
                  </label>

                  <label>
                    <span>Unidad de consumo</span>
                    <select name="recipeUnit" value={productForm.recipeUnit} onChange={onInputChange}>
                      {recipeUnits.map((unit) => (
                        <option key={unit}>{unit}</option>
                      ))}
                    </select>
                  </label>

                  <label>
                    <span>Notas</span>
                    <input
                      name="recipeNotes"
                      value={productForm.recipeNotes}
                      onChange={onInputChange}
                      placeholder="Ej. interiores, portada, laminado"
                    />
                  </label>
                </div>

                <div className="product-recipe-actions">
                  <button
                    type="button"
                    className="visual-outline-button"
                    onClick={onAddRecipeItem}
                    disabled={!canManageCatalog || !productForm.recipeSupplyId}
                  >
                    Agregar a receta
                  </button>
                </div>

                {normalizeProductRecipe(productForm.productionRecipe).length === 0 ? (
                  <div className="product-recipe-empty">
                    Sin receta configurada. El cálculo del lote usará el rendimiento general del insumo como respaldo.
                  </div>
                ) : (
                  <div className="product-recipe-list">
                    {normalizeProductRecipe(productForm.productionRecipe).map((item) => (
                      <article key={item.id} className="product-recipe-item">
                        <div>
                          <strong>{item.supplyName}</strong>
                          <span>
                            {item.quantityPerUnit} {item.unit} por {productForm.unit || "unidad"}
                          </span>
                          {item.notes && <small>{item.notes}</small>}
                        </div>
                        <button
                          type="button"
                          className="danger-table-button"
                          onClick={() => onRemoveRecipeItem(item.id)}
                          disabled={!canManageCatalog}
                        >
                          Quitar
                        </button>
                      </article>
                    ))}
                  </div>
                )}

                <p className="product-recipe-tip">
                  Tip: para rollos de laminado, configura el insumo con unidad base “Metro”.
                  La presentación puede ser “Rollo de 50 metros” y equivaler a 50 metros.
                </p>
              </div>

              <label className="full">
                <span>Observaciones</span>
                <textarea
                  name="notes"
                  value={productForm.notes}
                  onChange={onInputChange}
                  placeholder="Notas internas sobre uso, producción, plantillas o calidad."
                />
              </label>

              {formMessage && <div className="message-box">{formMessage}</div>}

              <div className="printshop-form-actions full">
                {selectedProductId && (
                  <button
                    type="button"
                    className="visual-outline-button"
                    onClick={onResetForm}
                  >
                    Nuevo producto
                  </button>
                )}

                <button
                  type="submit"
                  className="visual-primary-button"
                  disabled={savingProduct || !canManageCatalog}
                >
                  {savingProduct
                    ? "Guardando..."
                    : selectedProductId
                      ? "Guardar cambios"
                      : "Agregar producto"}
                </button>
              </div>
            </form>
          </Panel>
        </aside>
      </div>
    </section>
  );
}

function getPrintshopTabs(isAdmin) {
  return [
    { key: "dashboard", label: "Inicio", icon: "dashboard" },
    { key: "requests", label: "Solicitudes", icon: "requests" },
    { key: "certificates", label: "Certificados", icon: "certificates" },
    { key: "credentials", label: "Credenciales", icon: "credentials" },
    { key: "inventory", label: "Inventario terminado", icon: "inventory" },
    { key: "batches", label: "Lotes de producci\u00f3n", icon: "batches" },
    { key: "supplies", label: "Insumos", icon: "supplies" },
    { key: "catalog", label: "Cat\u00e1logo de productos", icon: "catalog" },
    { key: "templates", label: "Plantillas", icon: "templates", adminOnly: true },
    { key: "signers", label: "Firmas", icon: "signers", adminOnly: true },
    { key: "logs", label: "Bit\u00e1cora", icon: "logs" },
  ].filter((tab) => !tab.adminOnly || isAdmin);
}

function normalizePrintshopIconName(name) {
  const aliases = {
    "▤": "requests",
    "▥": "supplies",
    "▦": "workboard",
    "▧": "batches",
    "▨": "logs",
    "▣": "inventory",
    "✓": "ready",
    "!": "alert",
    "×": "critical",
    "↕": "movements",
    "↔": "movements",
    "↗": "trend",
    "↺": "history",
    "◷": "today",
    "⚑": "urgent",
    "●": "active",
    "◎": "target",
    "○": "inactive",
    "＋": "plus",
    "+": "plus",
    "✎": "edit",
    "✒": "signers",
    "≈": "capacity",
    "∆": "difference",
    "%": "percentage",
    "$": "value",
    "A": "adult",
    "K": "kids",
    "ℹ": "info",
    "☑": "certificates",
    "⚠": "warning",
    "👤": "users",
  };

  return aliases[name] || name || "dashboard";
}

function renderPrintshopIcon(icon) {
  return <PrintshopIcon name={icon} />;
}

